package com.ringoftime;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.client.config.ConfigManager;

/**
 * Keeps optional Custom UI Anchors data attached when a ring group changes identity.
 */
final class CustomUiAnchorsCompatibility
{
	private static final String CONFIG_GROUP = "anchorcustomizer";
	private static final String ASSIGNMENTS_KEY = "overlayAssignments";
	private static final String ORDER_KEY = "overlayOrder";
	private static final Type INTEGER_MAP_TYPE = new TypeToken<Map<String, Integer>>() { }.getType();

	private final ConfigManager configManager;
	private final Gson gson;

	CustomUiAnchorsCompatibility(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	void reconcile(Collection<TimerGroupOverlay> groups)
	{
		final Map<String, Integer> assignments = loadMap(ASSIGNMENTS_KEY);
		final Map<String, Integer> order = loadMap(ORDER_KEY);
		if (assignments == null && order == null)
		{
			return;
		}

		boolean assignmentsChanged = false;
		boolean orderChanged = false;
		for (TimerGroupOverlay group : groups)
		{
			final List<String> aliases = memberNames(group);
			assignmentsChanged |= reconcileNames(assignments, group.getName(), aliases);
			orderChanged |= reconcileNames(order, group.getName(), aliases);
		}

		saveIfChanged(ASSIGNMENTS_KEY, assignments, assignmentsChanged);
		saveIfChanged(ORDER_KEY, order, orderChanged);
	}

	void merge(TimerGroupOverlay source, TimerGroupOverlay destination)
	{
		final List<String> aliases = memberNames(destination);
		aliases.add(source.getName());
		reconcile(destination.getName(), aliases);
	}

	void detach(String detachedName)
	{
		removeName(ASSIGNMENTS_KEY, detachedName);
		removeName(ORDER_KEY, detachedName);
	}

	private void reconcile(String groupName, Collection<String> aliases)
	{
		final Map<String, Integer> assignments = loadMap(ASSIGNMENTS_KEY);
		final Map<String, Integer> order = loadMap(ORDER_KEY);
		saveIfChanged(
			ASSIGNMENTS_KEY,
			assignments,
			reconcileNames(assignments, groupName, aliases)
		);
		saveIfChanged(ORDER_KEY, order, reconcileNames(order, groupName, aliases));
	}

	private void removeName(String key, String name)
	{
		final Map<String, Integer> values = loadMap(key);
		if (values != null && values.remove(name) != null)
		{
			configManager.setConfiguration(CONFIG_GROUP, key, gson.toJson(values));
		}
	}

	private Map<String, Integer> loadMap(String key)
	{
		final String json = configManager.getConfiguration(CONFIG_GROUP, key);
		if (json == null || json.trim().isEmpty())
		{
			return null;
		}

		try
		{
			final Map<String, Integer> values = gson.fromJson(json, INTEGER_MAP_TYPE);
			return values == null ? new LinkedHashMap<>() : new LinkedHashMap<>(values);
		}
		catch (RuntimeException ignored)
		{
			return null;
		}
	}

	private void saveIfChanged(String key, Map<String, Integer> values, boolean changed)
	{
		if (values != null && changed)
		{
			configManager.setConfiguration(CONFIG_GROUP, key, gson.toJson(values));
		}
	}

	private static List<String> memberNames(TimerGroupOverlay group)
	{
		final List<String> names = new ArrayList<>();
		for (TimerCircleOverlay member : group.getMembers())
		{
			names.add(member.getName());
		}
		return names;
	}

	static boolean reconcileNames(
		Map<String, Integer> values,
		String groupName,
		Collection<String> aliases)
	{
		if (values == null)
		{
			return false;
		}

		Integer groupValue = values.get(groupName);
		boolean changed = false;
		for (String alias : aliases)
		{
			if (groupName.equals(alias))
			{
				continue;
			}

			final Integer aliasValue = values.remove(alias);
			if (aliasValue != null)
			{
				changed = true;
				if (groupValue == null)
				{
					groupValue = aliasValue;
				}
			}
		}

		if (groupValue != null && !groupValue.equals(values.get(groupName)))
		{
			values.put(groupName, groupValue);
			changed = true;
		}
		return changed;
	}
}

package com.ringoftime;

import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Constants;
import net.runelite.api.Skill;

/**
 * Tracks the exact per-skill durations supplied by divine-potion varbits.
 */
final class DivineTimerTracker
{
	static final int FULL_DURATION_TICKS = 500;

	private final Map<Skill, TimerSample> samples = new EnumMap<>(Skill.class);

	void reset()
	{
		samples.clear();
	}

	/**
	 * Updates all five skills affected by divine potions from one client sample.
	 * Combination-potion variables identify Defence as divine even when a
	 * Moonlight potion happens to expose the same underlying Defence timer.
	 */
	void observe(
		int attackTicks,
		int strengthTicks,
		int defenceTicks,
		int rangedTicks,
		int magicTicks,
		int combatTicks,
		int bastionTicks,
		int battlemageTicks,
		int moonlightTicks,
		long sampleMillis)
	{
		setRemainingTicks(Skill.ATTACK, attackTicks, sampleMillis);
		setRemainingTicks(Skill.STRENGTH, strengthTicks, sampleMillis);
		setRemainingTicks(Skill.RANGED, rangedTicks, sampleMillis);
		setRemainingTicks(Skill.MAGIC, magicTicks, sampleMillis);

		final boolean combinationProtectsDefence = combatTicks >= defenceTicks
			|| bastionTicks >= defenceTicks
			|| battlemageTicks >= defenceTicks;
		final boolean moonlightOnly = defenceTicks > 0
			&& moonlightTicks > 0
			&& !combinationProtectsDefence
			&& moonlightTicks + 1 >= defenceTicks;
		setRemainingTicks(Skill.DEFENCE, moonlightOnly ? 0 : defenceTicks, sampleMillis);
	}

	boolean isActive(Skill skill)
	{
		return samples.containsKey(skill);
	}

	double getProgress(Skill skill, long nowMillis)
	{
		final double ticks = getRemainingTicks(skill, nowMillis);
		return clamp(ticks / FULL_DURATION_TICKS);
	}

	int getRemainingSeconds(Skill skill, long nowMillis)
	{
		final double ticks = getRemainingTicks(skill, nowMillis);
		return (int) Math.ceil(ticks * Constants.GAME_TICK_LENGTH / 1000d);
	}

	private double getRemainingTicks(Skill skill, long nowMillis)
	{
		final TimerSample sample = samples.get(skill);
		if (sample == null)
		{
			return 0d;
		}

		final long elapsedMillis = Math.max(0L, nowMillis - sample.sampleMillis);
		return Math.max(
			0d,
			sample.remainingTicks - elapsedMillis / (double) Constants.GAME_TICK_LENGTH
		);
	}

	private void setRemainingTicks(Skill skill, int ticks, long sampleMillis)
	{
		if (ticks <= 0)
		{
			samples.remove(skill);
		}
		else
		{
			final int clampedTicks = Math.min(FULL_DURATION_TICKS, ticks);
			final TimerSample previous = samples.get(skill);
			if (previous == null || previous.remainingTicks != clampedTicks)
			{
				samples.put(skill, new TimerSample(clampedTicks, sampleMillis));
			}
		}
	}

	private static double clamp(double value)
	{
		return Math.max(0d, Math.min(1d, value));
	}

	private static final class TimerSample
	{
		private final int remainingTicks;
		private final long sampleMillis;

		private TimerSample(int remainingTicks, long sampleMillis)
		{
			this.remainingTicks = remainingTicks;
			this.sampleMillis = sampleMillis;
		}
	}
}

package com.ringoftime;

import com.ringoftime.EffectTimerTracker.Effect;
import com.ringoftime.RingOfTimeConfig.PlusMinusPosition;
import com.ringoftime.RingOfTimeConfig.TimerPosition;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.Rectangle;
import java.awt.geom.Arc2D;
import net.runelite.api.Client;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.FontManager;

/**
 * Renders one independently draggable non-skill effect timer.
 *
 * <p>The toxin instance switches between poison and venom instead of creating
 * overlapping entities for mutually exclusive states. Regular and super
 * antifire remain separate entities because both game variables can exist and
 * have different countdown scales.</p>
 */
final class EffectTimerOverlay extends TimerCircleOverlay
{
	private static final int ARC_START_DEGREES = 90;
	private static final int TEXT_SHADOW_OFFSET = 1;

	private final Client client;
	private final RingOfTimePlugin plugin;
	private final RingOfTimeConfig config;
	private final Effect effect;
	private volatile Image primaryIcon;
	private final Image alternateIcon;

	/**
	 * Creates one persistent RuneLite overlay key for one effect family.
	 */
	EffectTimerOverlay(
		Client client,
		RingOfTimePlugin plugin,
		RingOfTimeConfig config,
		ItemManager itemManager,
		SpriteManager spriteManager,
		Effect effect)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.effect = effect;
		this.primaryIcon = loadPrimaryIcon(itemManager, effect);
		if (effect == Effect.THRALL && spriteManager != null)
		{
			spriteManager.getSpriteAsync(
				SpriteID.MagicNecroOn.RESURRECT_SUPERIOR_SKELETON,
				0,
				image -> primaryIcon = image
			);
		}
		this.alternateIcon = itemManager != null
			&& (effect == Effect.TOXIN || effect == Effect.ANTIPOISON)
			? itemManager.getImage(ItemID.ANTIVENOM4)
			: null;

	}

	@Override
	public String getName()
	{
		return getOverlayName(effect);
	}

	static String getOverlayName(Effect effect)
	{
		switch (effect)
		{
			case TOXIN:
				return persistentName("Poison and Venom");
			case ANTIPOISON:
				return persistentName("Antipoison Protection");
			case STAMINA:
				return persistentName("Stamina");
			case ANTIFIRE:
				return persistentName("Antifire");
			case SUPER_ANTIFIRE:
				return persistentName("Super Antifire");
			case PRAYER_REGENERATION:
				return persistentName("Prayer Regeneration");
			case THRALL:
				return persistentName("Thrall");
			default:
				return persistentName("Effect");
		}
	}

	/**
	 * Draws this effect only while both active and enabled in configuration.
	 */
	@Override
	public Dimension render(Graphics2D graphics)
	{
		final EffectTimerTracker tracker = plugin.getEffectTracker();
		if (!isTimerActive())
		{
			return null;
		}

		final int size = config.ringSize();
		final int currentTick = client.getTickCount();
		final double subTickProgress = plugin.getSubTickProgress();
		final int remainingSeconds = tracker.getRemainingSeconds(
			effect,
			currentTick,
			subTickProgress
		);
		final TimerPosition timerPosition = config.timerPosition();
		final String timeText = !timerPosition.isShown()
			? null
			: formatDuration(remainingSeconds);
		final PlusMinusPosition plusMinusPosition = effect == Effect.TOXIN
			? config.debuffPlusMinusPosition()
			: PlusMinusPosition.OFF;
		final String plusMinusText = plusMinusPosition == PlusMinusPosition.OFF
			? null
			: Integer.toString(tracker.getNextToxinDamage());
		final Font plusMinusFont = FontManager.getRunescapeBoldFont().deriveFont((float) config.plusMinusFontSize());
		final boolean poisonInnerRingVisible = effect == Effect.TOXIN
			&& tracker.hasMultiplePoisonCycles()
			&& config.poisonInnerRing().isShown();
		final boolean thrallCooldownVisible = effect == Effect.THRALL
			&& tracker.isThrallCooldownActive();
		final boolean prayerRegenerationCycleVisible = effect == Effect.PRAYER_REGENERATION;
		final boolean innerRingVisible = poisonInnerRingVisible
			|| thrallCooldownVisible
			|| prayerRegenerationCycleVisible;
		final int thickness = Math.min(config.ringThickness(), Math.max(2, size / 3));
		final int outlineThickness = config.showRingOutline() ? config.outlineThickness() : 0;
		final int clearCenterSize = TimerLabelLayout.getClearCenterSize(
			size,
			thickness,
			outlineThickness,
			innerRingVisible
		);
		final Font preferredTimerFont = FontManager.getRunescapeBoldFont()
			.deriveFont((float) config.timerFontSize());
		final Font timerFont = TimerLabelLayout.fitTimerFont(
			graphics,
			preferredTimerFont,
			timeText,
			clearCenterSize
		);
		final TimerLabelLayout labelLayout = TimerLabelLayout.create(
			size,
			graphics.getFontMetrics(timerFont),
			timeText,
			timerPosition,
			graphics.getFontMetrics(plusMinusFont),
			plusMinusText,
			plusMinusPosition,
			config.effectIconPosition()
		);

		final Graphics2D canvas = (Graphics2D) graphics.create();
		try
		{
			canvas.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			canvas.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			canvas.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
			canvas.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);
			canvas.translate(labelLayout.getRingX(), labelLayout.getRingY());
			drawTimer(
				canvas,
				tracker,
				size,
				currentTick,
				subTickProgress,
				remainingSeconds,
				timeText,
				plusMinusText,
				timerFont,
				plusMinusFont,
				labelLayout
			);
		}
		finally
		{
			canvas.dispose();
		}

		return labelLayout.getDimension();
	}

	/**
	 * Draws the effect ring, optional poison cycle, positioned icon, and labels.
	 */
	private void drawTimer(
		Graphics2D graphics,
		EffectTimerTracker tracker,
		int size,
		int currentTick,
		double subTickProgress,
		int remainingSeconds,
		String timeText,
		String plusMinusText,
		Font timerFont,
		Font plusMinusFont,
		TimerLabelLayout labelLayout)
	{
		final Color activeColor = getActiveColor(tracker);
		final int thickness = Math.min(config.ringThickness(), Math.max(2, size / 3));
		final int outlineThickness = config.showRingOutline() ? config.outlineThickness() : 0;
		final double edgeMargin = Math.max(1d, outlineThickness);
		final double inset = thickness / 2d + edgeMargin;
		final double diameter = size - thickness - edgeMargin * 2d;
		final Arc2D.Double ring = new Arc2D.Double(
			inset,
			inset,
			diameter,
			diameter,
			ARC_START_DEGREES,
			-360d,
			Arc2D.OPEN
		);

		if (config.showRingOutline())
		{
			graphics.setStroke(new BasicStroke(
				thickness + outlineThickness * 2,
				BasicStroke.CAP_ROUND,
				BasicStroke.JOIN_ROUND
			));
			graphics.setColor(effect == Effect.TOXIN
				? config.debuffOutlineColor()
				: config.effectOutlineColor());
			graphics.draw(ring);
		}

		/*
		 * Venom uses a complete poison-green track under its dark-green active
		 * arc. An actual conversion turns this entity into the poison countdown.
		 */
		final boolean venom = effect == Effect.TOXIN && tracker.isVenom();
		final Color trackColor = venom ? config.poisonColor() : config.emptyRingColor();
		graphics.setStroke(new BasicStroke(thickness, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		graphics.setColor(trackColor);
		graphics.draw(ring);

		ring.setAngleExtent(-360d * tracker.getOverallProgress(effect, currentTick, subTickProgress));
		graphics.setColor(activeColor);
		graphics.draw(ring);

		if (effect != Effect.TOXIN)
		{
			final Color flashColor = effect == Effect.THRALL
				? config.thrallFlashColor()
				: activeColor;
			drawExpiryFlash(
				graphics,
				ring,
				thickness,
				flashColor,
				remainingSeconds,
				currentTick,
				subTickProgress
			);
		}

		if (effect == Effect.TOXIN
			&& tracker.hasMultiplePoisonCycles()
			&& config.poisonInnerRing().isShown())
		{
			drawInnerRing(
				graphics,
				size,
				thickness,
				outlineThickness,
				tracker.getNextPoisonHitProgress(currentTick, subTickProgress),
				config.toxinInnerRingColor(),
				config.debuffOutlineColor()
			);
		}
		else if (effect == Effect.THRALL && tracker.isThrallCooldownActive())
		{
			drawInnerRing(
				graphics,
				size,
				thickness,
				outlineThickness,
				tracker.getThrallCooldownProgress(currentTick, subTickProgress),
				config.buffInnerRingColor(),
				config.effectOutlineColor()
			);
		}
		else if (effect == Effect.PRAYER_REGENERATION)
		{
			drawInnerRing(
				graphics,
				size,
				thickness,
				outlineThickness,
				tracker.getPrayerRegenerationCycleProgress(currentTick, subTickProgress),
				config.buffInnerRingColor(),
				config.effectOutlineColor()
			);
		}

		final boolean alternateProtectionIcon = effect == Effect.ANTIPOISON
			&& tracker.isAntivenomProtection();
		drawIcon(
			graphics,
			labelLayout.getIconBounds(),
			venom || alternateProtectionIcon ? alternateIcon : primaryIcon
		);
		drawLabel(
			graphics,
			timeText,
			labelLayout.getTimerBounds(),
			Color.WHITE,
			timerFont,
			false
		);
		drawLabel(
			graphics,
			plusMinusText,
			labelLayout.getPlusMinusBounds(),
			config.debuffPlusMinusColor(),
			plusMinusFont,
			true
		);
	}
	/**
	 * Flashes beneficial effects in their own configured color near expiry.
	 */
	private void drawExpiryFlash(
		Graphics2D graphics,
		Arc2D.Double ring,
		int thickness,
		Color color,
		int remainingSeconds,
		int currentTick,
		double subTickProgress)
	{
		if (!config.flashExpiringBuffs()
			|| remainingSeconds <= 0
			|| remainingSeconds > config.flashThresholdSeconds())
		{
			return;
		}

		final long elapsedMillis = Math.round(
			(currentTick + subTickProgress) * net.runelite.api.Constants.GAME_TICK_LENGTH
		);
		final boolean brightPhase = (elapsedMillis / 300L) % 2L == 0L;
		final int pulseAlpha = Math.min(color.getAlpha(), brightPhase ? 235 : 55);
		ring.setAngleExtent(-360d);
		graphics.setStroke(new BasicStroke(thickness, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), pulseAlpha));
		graphics.draw(ring);
	}

	/**
	 * Draws a secondary countdown inside an effect's total-duration ring.
	 */
	private void drawInnerRing(
		Graphics2D graphics,
		int size,
		int outerThickness,
		int outlineThickness,
		double progress,
		Color activeColor,
		Color outlineColor)
	{
		final int innerThickness = Math.max(2, Math.min(4, (outerThickness + 1) / 2));
		final double gap = Math.max(2d, outerThickness * 0.35d);
		final double edgeMargin = Math.max(1d, outlineThickness);
		final double inset = outerThickness
			+ edgeMargin
			+ outlineThickness
			+ gap
			+ innerThickness / 2d;
		final double diameter = size - inset * 2d;
		if (diameter < 10d)
		{
			return;
		}

		final Arc2D.Double innerRing = new Arc2D.Double(
			inset,
			inset,
			diameter,
			diameter,
			ARC_START_DEGREES,
			-360d,
			Arc2D.OPEN
		);
		if (config.showRingOutline())
		{
			graphics.setStroke(new BasicStroke(
				innerThickness + outlineThickness * 2,
				BasicStroke.CAP_ROUND,
				BasicStroke.JOIN_ROUND
			));
			graphics.setColor(outlineColor);
			graphics.draw(innerRing);
		}

		graphics.setStroke(new BasicStroke(innerThickness, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		graphics.setColor(withReducedAlpha(config.emptyRingColor()));
		graphics.draw(innerRing);

		innerRing.setAngleExtent(-360d * progress);
		graphics.setColor(activeColor);
		graphics.draw(innerRing);
	}

	/**
	 * Applies each requested default color to its effect family.
	 */
	private Color getActiveColor(EffectTimerTracker tracker)
	{
		switch (effect)
		{
			case TOXIN:
				return tracker.isVenom() ? config.venomColor() : config.poisonColor();
			case ANTIPOISON:
				return tracker.isAntivenomProtection()
					? config.antivenomProtectionColor()
					: config.antipoisonColor();
			case STAMINA:
				return config.staminaColor();
			case ANTIFIRE:
			case SUPER_ANTIFIRE:
				return config.antifireColor();
			case PRAYER_REGENERATION:
				return config.prayerRegenerationColor();
			case THRALL:
				return config.thrallColor();
			default:
				return Color.WHITE;
		}
	}

	/**
	 * Includes this effect in automatic stacking only while its authoritative
	 * state is active and its Effects-section switch is enabled.
	 */
	@Override
	boolean isTimerActive()
	{
		return plugin.getEffectTracker().isActive(effect) && isConfiguredVisible();
	}

	/**
	 * Applies the Effects-section enable switches.
	 */
	private boolean isConfiguredVisible()
	{
		switch (effect)
		{
			case TOXIN:
				return config.debuffDisplay().showsPoisonVenom();
			case ANTIPOISON:
				return config.showAntipoison();
			case STAMINA:
				return config.showStamina();
			case ANTIFIRE:
			case SUPER_ANTIFIRE:
				return config.showAntifire();
			case PRAYER_REGENERATION:
				return config.showPrayerRegeneration();
			case THRALL:
				return config.showThrall();
			default:
				return false;
		}
	}

	private static Image loadPrimaryIcon(ItemManager itemManager, Effect effect)
	{
		if (itemManager == null || effect == Effect.THRALL)
		{
			return null;
		}

		switch (effect)
		{
			case TOXIN:
				return itemManager.getImage(ItemID._4DOSEANTIPOISON);
			case ANTIPOISON:
				return itemManager.getImage(ItemID._4DOSEANTIPOISON);
			case STAMINA:
				return itemManager.getImage(ItemID._4DOSESTAMINA);
			case ANTIFIRE:
				return itemManager.getImage(ItemID._4DOSE1ANTIDRAGON);
			case SUPER_ANTIFIRE:
				return itemManager.getImage(ItemID._4DOSE3ANTIDRAGON);
			case PRAYER_REGENERATION:
				return itemManager.getImage(ItemID._4DOSE1PRAYER_REGENERATION);
			default:
				return null;
		}
	}

	/**
	 * Scales the effect image into its configured icon slot.
	 */
	private static void drawIcon(Graphics2D graphics, Rectangle bounds, Image icon)
	{
		if (icon == null)
		{
			return;
		}

		final int sourceWidth = Math.max(1, icon.getWidth(null));
		final int sourceHeight = Math.max(1, icon.getHeight(null));
		final double scale = Math.min(
			1d,
			Math.min(bounds.width / (double) sourceWidth, bounds.height / (double) sourceHeight)
		);
		final int iconWidth = Math.max(1, (int) Math.round(sourceWidth * scale));
		final int iconHeight = Math.max(1, (int) Math.round(sourceHeight * scale));
		graphics.drawImage(
			icon,
			bounds.x + (bounds.width - iconWidth) / 2,
			bounds.y + (bounds.height - iconHeight) / 2,
			iconWidth,
			iconHeight,
			null
		);
	}

	/**
	 * Draws fitted timer text without a background, or a +/- value with its
	 * configurable badge background.
	 */
	private void drawLabel(
		Graphics2D graphics,
		String text,
		Rectangle bounds,
		Color textColor,
		Font font,
		boolean drawBackground)
	{
		if (text == null || bounds == null)
		{
			return;
		}

		final FontMetrics metrics = graphics.getFontMetrics(font);
		final int textX = bounds.x + (bounds.width - metrics.stringWidth(text)) / 2;
		final int baselineY = bounds.y + (bounds.height - metrics.getHeight()) / 2
			+ metrics.getAscent();

		if (drawBackground)
		{
			graphics.setColor(config.plusMinusBackgroundColor());
			graphics.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 6, 6);
		}
		graphics.setFont(font);
		graphics.setColor(new Color(0, 0, 0, 235));
		graphics.drawString(
			text,
			textX + TEXT_SHADOW_OFFSET,
			baselineY + TEXT_SHADOW_OFFSET
		);
		graphics.setColor(textColor);
		graphics.drawString(text, textX, baselineY);
	}

	private static Color withReducedAlpha(Color color)
	{
		return new Color(
			color.getRed(),
			color.getGreen(),
			color.getBlue(),
			Math.max(30, color.getAlpha() / 2)
		);
	}

	private static String formatDuration(int totalSeconds)
	{
		if (totalSeconds < 60)
		{
			return totalSeconds + "s";
		}

		final int minutes = totalSeconds / 60;
		final int seconds = totalSeconds % 60;
		return minutes + ":" + (seconds < 10 ? "0" : "") + seconds;
	}
}

package com.ringoftime;

import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Constants;

/**
 * Tracks non-skill effect durations exposed by RuneLite game variables.
 *
 * <p>Stamina and the two antifire strengths use coarse game varbits: their
 * values decrease in blocks of several game ticks. {@link Countdown} anchors
 * each block to the tick on which its value changes so the overlay can animate
 * smoothly between those changes.</p>
 *
 * <p>Poison and venom share one varplayer. Ordinary poison decreases toward
 * zero and therefore has a total natural-cure projection. Venom instead grows
 * in severity and never naturally becomes poison, so its visual represents the
 * repeating time until the next venom hit.</p>
 */
final class EffectTimerTracker
{
	/**
	 * Identifies each independently draggable effect-circle overlay.
	 */
	enum Effect
	{
		TOXIN,
		ANTIPOISON,
		STAMINA,
		ANTIFIRE,
		SUPER_ANTIFIRE,
		PRAYER_REGENERATION,
		THRALL
	}

	static final int POISON_CYCLE_MILLIS = 18_200;
	static final int ANTIPOISON_CYCLE_TICKS = 30;
	static final int ANTIVENOM_CUTOFF = -38;
	static final int VENOM_THRESHOLD = 1_000_000;
	static final int VENOM_MAX_DAMAGE = 20;
	static final int STAMINA_UNIT_TICKS = 10;
	static final int PRAYER_REGENERATION_UNIT_TICKS = 12;
	static final int ANTIFIRE_UNIT_TICKS = 30;
	static final int SUPER_ANTIFIRE_UNIT_TICKS = 20;
	static final int THRALL_COOLDOWN_TICKS = 17;

	private final Map<Effect, Countdown> countdowns = new EnumMap<>(Effect.class);
	private final Countdown thrallCooldown = new Countdown(1);
	private int poisonValue;
	private int poisonPeakValue;
	private int poisonCycleStartTick = -1;
	private boolean poisonEstimated = true;
	private boolean antivenomProtection;

	EffectTimerTracker()
	{
		countdowns.put(Effect.ANTIPOISON, new Countdown(1));
		countdowns.put(Effect.STAMINA, new Countdown(STAMINA_UNIT_TICKS));
		countdowns.put(Effect.PRAYER_REGENERATION, new Countdown(PRAYER_REGENERATION_UNIT_TICKS));
		countdowns.put(Effect.ANTIFIRE, new Countdown(ANTIFIRE_UNIT_TICKS));
		countdowns.put(Effect.SUPER_ANTIFIRE, new Countdown(SUPER_ANTIFIRE_UNIT_TICKS));
		countdowns.put(Effect.THRALL, new Countdown(1));
	}

	/**
	 * Removes all effect state, such as when the player logs out or hops.
	 */
	void reset()
	{
		poisonValue = 0;
		poisonPeakValue = 0;
		poisonCycleStartTick = -1;
		poisonEstimated = true;
		antivenomProtection = false;

		for (Countdown countdown : countdowns.values())
		{
			countdown.reset();
		}
		thrallCooldown.reset();
	}

	void observePoison(int value, int currentTick, boolean exactChange)
	{
		if (value <= 0)
		{
			poisonValue = 0;
			poisonPeakValue = 0;
			poisonCycleStartTick = -1;
			poisonEstimated = true;
			return;
		}

		final boolean wasActive = poisonValue > 0;
		final boolean wasVenom = isVenomValue(poisonValue);
		final boolean isVenom = isVenomValue(value);
		final boolean changed = value != poisonValue;
		final boolean naturalPoisonTick = wasActive
			&& !wasVenom
			&& !isVenom
			&& value == poisonValue - 1;

		if (!wasActive || changed)
		{
			poisonCycleStartTick = currentTick;
			poisonEstimated = !exactChange;
		}

		if (!isVenom)
		{
			/*
			 * Keep the initial poison severity as the denominator across
			 * ordinary one-step decay. A cure, re-poison, or venom-to-poison
			 * conversion starts a new full total-cure visual.
			 */
			if (!wasActive || wasVenom || (changed && !naturalPoisonTick))
			{
				poisonPeakValue = value;
			}
			else
			{
				poisonPeakValue = Math.max(poisonPeakValue, value);
			}
		}
		else
		{
			// Venom has no finite peak or natural-cure duration.
			poisonPeakValue = 0;
		}

		poisonValue = value;
	}

	void observeAntipoison(int value, int currentTick, boolean exactChange)
	{
		final Countdown protection = countdowns.get(Effect.ANTIPOISON);
		if (value >= 0)
		{
			protection.reset();
			antivenomProtection = false;
			return;
		}

		final boolean newAntivenomProtection = value < ANTIVENOM_CUTOFF;
		if (protection.isActive() && newAntivenomProtection != antivenomProtection)
		{
			// A protection-type transition starts a fresh independent total ring.
			protection.reset();
		}

		final int remainingTicks = newAntivenomProtection
			? ANTIPOISON_CYCLE_TICKS
				+ Math.abs((value + 1 - ANTIVENOM_CUTOFF) * ANTIPOISON_CYCLE_TICKS)
			: ANTIPOISON_CYCLE_TICKS
				+ Math.abs((value + 1) * ANTIPOISON_CYCLE_TICKS);
		protection.observe(remainingTicks, true, currentTick, exactChange);
		antivenomProtection = newAntivenomProtection;
	}

	/**
	 * Reports which icon and color the shared protection circle should use.
	 */
	boolean isAntivenomProtection()
	{
		return isActive(Effect.ANTIPOISON) && antivenomProtection;
	}

	/**
	 * Observes the stamina varbits.
	 */
	void observeStamina(int durationUnits, boolean effectActive, int currentTick, boolean exactChange)
	{
		countdowns.get(Effect.STAMINA).observe(
			durationUnits,
			effectActive,
			currentTick,
			exactChange
		);
	}

	void observePrayerRegeneration(int durationUnits, int currentTick, boolean exactChange)
	{
		countdowns.get(Effect.PRAYER_REGENERATION).observe(
			durationUnits,
			durationUnits > 0,
			currentTick,
			exactChange
		);
	}

	double getPrayerRegenerationCycleProgress(int currentTick, double subTickProgress)
	{
		return countdowns.get(Effect.PRAYER_REGENERATION)
			.getUnitProgress(currentTick, subTickProgress);
	}

	/**
	 * Observes regular and super-antifire varbits independently.
	 */
	void observeAntifire(
		int antifireUnits,
		int superAntifireUnits,
		int currentTick,
		boolean exactChange)
	{
		countdowns.get(Effect.ANTIFIRE).observe(
			antifireUnits,
			antifireUnits > 0,
			currentTick,
			exactChange
		);
		countdowns.get(Effect.SUPER_ANTIFIRE).observe(
			superAntifireUnits,
			superAntifireUnits > 0,
			currentTick,
			exactChange
		);
	}

	void startThrall(int boostedMagicLevel, boolean masterCombatAchievements, int currentTick)
	{
		final int durationTicks = Math.max(0, boostedMagicLevel)
			* (masterCombatAchievements ? 2 : 1);
		final Countdown thrall = countdowns.get(Effect.THRALL);
		thrall.reset();
		thrall.observe(durationTicks, durationTicks > 0, currentTick, true);
	}

	void observeThrallCooldown(boolean active, int currentTick)
	{
		thrallCooldown.observe(THRALL_COOLDOWN_TICKS, active, currentTick, true);
	}

	boolean isThrallCooldownActive()
	{
		return thrallCooldown.isActive();
	}

	double getThrallCooldownProgress(int currentTick, double subTickProgress)
	{
		return thrallCooldown.getProgress(currentTick, subTickProgress);
	}

	void observeThrallActive(boolean active)
	{
		if (!active)
		{
			countdowns.get(Effect.THRALL).reset();
		}
	}

	/**
	 * Reports whether an effect circle currently has meaningful state.
	 */
	boolean isActive(Effect effect)
	{
		return effect == Effect.TOXIN
			? poisonValue > 0
			: countdowns.get(effect).isActive();
	}

	/**
	 * Reports whether the shared toxin circle is currently venomous.
	 */
	boolean isVenom()
	{
		return isVenomValue(poisonValue);
	}

	/**
	 * Calculates the fraction of the effect represented by the outer ring.
	 */
	double getOverallProgress(Effect effect, int currentTick, double subTickProgress)
	{
		if (!isActive(effect))
		{
			return 0d;
		}

		if (effect != Effect.TOXIN)
		{
			return countdowns.get(effect).getProgress(currentTick, subTickProgress);
		}

		final double cycleProgress = getPoisonCycleProgress(currentTick, subTickProgress);
		if (isVenom())
		{
			// Venom's outer ring is its repeating next-hit cycle.
			return cycleProgress;
		}

		final int peak = Math.max(poisonValue, poisonPeakValue);
		return clamp((poisonValue - 1d + cycleProgress) / peak);
	}

	/**
	 * Avoids drawing a duplicate inner ring during poison's final cycle.
	 */
	boolean hasMultiplePoisonCycles()
	{
		return poisonValue > 1 && !isVenom();
	}
	/**
	 * Returns poison's inner-ring progress until its next damage tick.
	 */
	double getNextPoisonHitProgress(int currentTick, double subTickProgress)
	{
		return poisonValue > 0 && !isVenom()
			? getPoisonCycleProgress(currentTick, subTickProgress)
			: 0d;
	}

	/**
	 * Projects the seconds represented by an effect's timer label.
	 *
	 * <p>For poison this is time to natural cure. For venom it is time to the
	 * next hit because venom has no natural expiry.</p>
	 */
	int getRemainingSeconds(Effect effect, int currentTick, double subTickProgress)
	{
		if (!isActive(effect))
		{
			return 0;
		}

		if (effect != Effect.TOXIN)
		{
			final double ticks = countdowns.get(effect).getRemainingTicks(currentTick, subTickProgress);
			return ticksToSeconds(ticks);
		}

		final double cycleProgress = getPoisonCycleProgress(currentTick, subTickProgress);
		final double milliseconds = isVenom()
			? cycleProgress * POISON_CYCLE_MILLIS
			: (poisonValue - 1d + cycleProgress) * POISON_CYCLE_MILLIS;
		return (int) Math.ceil(milliseconds / 1000d);
	}

	/**
	 * Returns the next poison or venom damage shown in the circle's badge.
	 */
	int getNextToxinDamage()
	{
		if (poisonValue <= 0)
		{
			return 0;
		}

		if (isVenom())
		{
			final int scaledValue = poisonValue - VENOM_THRESHOLD + 3;
			return Math.min(VENOM_MAX_DAMAGE, scaledValue * 2);
		}

		return (int) Math.ceil(poisonValue / 5d);
	}

	/**
	 * Reports whether a timer's first partial interval is only estimated.
	 */
	boolean isEstimated(Effect effect)
	{
		return effect == Effect.TOXIN
			? poisonValue > 0 && poisonEstimated
			: countdowns.get(effect).isEstimated();
	}

	/**
	 * Calculates remaining progress in the current poison/venom damage cycle.
	 */
	private double getPoisonCycleProgress(int currentTick, double subTickProgress)
	{
		if (poisonCycleStartTick < 0)
		{
			return 0d;
		}

		final double elapsedTicks = Math.max(
			0d,
			currentTick - poisonCycleStartTick + clamp(subTickProgress)
		);
		final double elapsedMillis = elapsedTicks * Constants.GAME_TICK_LENGTH;
		return clamp(1d - elapsedMillis / POISON_CYCLE_MILLIS);
	}

	private static boolean isVenomValue(int value)
	{
		return value >= VENOM_THRESHOLD;
	}

	private static int ticksToSeconds(double ticks)
	{
		return (int) Math.ceil(ticks * Constants.GAME_TICK_LENGTH / 1000d);
	}

	private static double clamp(double value)
	{
		return Math.max(0d, Math.min(1d, value));
	}

	/**
	 * Smooths one coarse remaining-duration varbit into a continuous countdown.
	 */
	private static final class Countdown
	{
		private final int ticksPerUnit;
		private int rawUnits;
		private int anchorTick = -1;
		private double remainingTicksAtAnchor;
		private double totalTicks;
		private boolean estimated = true;

		private Countdown(int ticksPerUnit)
		{
			this.ticksPerUnit = ticksPerUnit;
		}

		private void observe(int units, boolean enabled, int currentTick, boolean exactChange)
		{
			if (!enabled || units <= 0)
			{
				reset();
				return;
			}

			final boolean wasActive = isActive();
			if (!wasActive || units != rawUnits)
			{
				final double newRemainingTicks = units * (double) ticksPerUnit;

				/*
				 * A larger value is a refresh and starts a new full ring.
				 * Normal decreases preserve the original denominator.
				 */
				if (!wasActive || units > rawUnits)
				{
					totalTicks = newRemainingTicks;
				}

				rawUnits = units;
				remainingTicksAtAnchor = newRemainingTicks;
				anchorTick = currentTick;
				estimated = !exactChange;
			}
		}

		private boolean isActive()
		{
			return anchorTick >= 0 && rawUnits > 0;
		}

		private double getProgress(int currentTick, double subTickProgress)
		{
			if (!isActive() || totalTicks <= 0d)
			{
				return 0d;
			}
			return clamp(getRemainingTicks(currentTick, subTickProgress) / totalTicks);
		}

		private double getUnitProgress(int currentTick, double subTickProgress)
		{
			if (!isActive())
			{
				return 0d;
			}

			final double elapsed = Math.max(
				0d,
				currentTick - anchorTick + clamp(subTickProgress)
			);
			return clamp(1d - elapsed / ticksPerUnit);
		}

		private double getRemainingTicks(int currentTick, double subTickProgress)
		{
			if (!isActive())
			{
				return 0d;
			}

			final double elapsed = Math.max(
				0d,
				currentTick - anchorTick + clamp(subTickProgress)
			);
			return Math.max(0d, remainingTicksAtAnchor - elapsed);
		}

		private boolean isEstimated()
		{
			return isActive() && estimated;
		}

		private void reset()
		{
			rawUnits = 0;
			anchorTick = -1;
			remainingTicksAtAnchor = 0d;
			totalTicks = 0d;
			estimated = true;
		}
	}
}

package com.ringoftime;

import java.awt.Color;
import net.runelite.api.Skill;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

/**
 * Declares every user-facing setting shown in RuneLite's configuration panel.
 *
 * <p>Buffs, debuffs, and non-skill effects have separate sections so users can
 * tune each timer family without changing the others.</p>
 */
@ConfigGroup(RingOfTimeConfig.GROUP)
public interface RingOfTimeConfig extends Config
{
	String GROUP = "ring-of-time";

	/**
	 * Selects which category of restorable skill changes appears in the overlay.
	 */
	enum TrackedSkills
	{
		COMBAT("Combat"),
		NON_COMBAT("Non-combat"),
		ALL("All");

		private final String displayName;

		TrackedSkills(String displayName)
		{
			this.displayName = displayName;
		}

		@Override
		public String toString()
		{
			return displayName;
		}
	}

	/**
	 * Selects which kinds of harmful timers appear.
	 */
	enum DebuffDisplay
	{
		SKILLS("Skills"),
		POISON_VENOM("Poison/venom"),
		BOTH("Both"),
		OFF("Off");

		private final String displayName;

		DebuffDisplay(String displayName)
		{
			this.displayName = displayName;
		}

		boolean showsSkills()
		{
			return this == SKILLS || this == BOTH;
		}

		boolean showsPoisonVenom()
		{
			return this == POISON_VENOM || this == BOTH;
		}

		@Override
		public String toString()
		{
			return displayName;
		}
	}
	/**
	 * Controls where the countdown appears inside the ring.
	 */
	enum TimerPosition
	{
		TOP("Top"),
		MIDDLE("Middle"),
		BOTTOM("Bottom"),
		OFF("Off");

		private final String displayName;

		TimerPosition(String displayName)
		{
			this.displayName = displayName;
		}

		boolean isShown()
		{
			return this != OFF;
		}

		@Override
		public String toString()
		{
			return displayName;
		}
	}

	/**
	 * Controls where the skill or effect icon appears around its ring.
	 */
	enum IconPosition
	{
		TOP_LEFT("Top left"),
		TOP_RIGHT("Top right"),
		BOTTOM_RIGHT("Bottom right"),
		BOTTOM_LEFT("Bottom left"),
		CENTER("Center of circle"),
		ABOVE_RING("Above ring"),
		UNDER_RING("Under ring");

		private final String displayName;

		IconPosition(String displayName)
		{
			this.displayName = displayName;
		}

		@Override
		public String toString()
		{
			return displayName;
		}
	}

	/**
	 * Provides an explicit on/off dropdown for one inner-ring category.
	 */
	enum InnerRingDisplay
	{
		SHOW("On"),
		HIDE("Off");

		private final String displayName;

		InnerRingDisplay(String displayName)
		{
			this.displayName = displayName;
		}

		boolean isShown()
		{
			return this == SHOW;
		}

		@Override
		public String toString()
		{
			return displayName;
		}
	}

	/**
	 * Controls the number shown in a buff or debuff +/- badge.
	 */
	enum LevelDisplay
	{
		CHANGE("Change (+/-)"),
		TOTAL_LEVEL("Total level");

		private final String displayName;

		LevelDisplay(String displayName)
		{
			this.displayName = displayName;
		}

		@Override
		public String toString()
		{
			return displayName;
		}
	}

	/**
	 * Controls where the signed level-change badge appears.
	 */
	enum PlusMinusPosition
	{
		TOP_LEFT("Top left"),
		TOP_RIGHT("Top right"),
		BOTTOM_RIGHT("Bottom right"),
		BOTTOM_LEFT("Bottom left"),
		CENTER("Center of circle"),
		OFF("Off");

		private final String displayName;

		PlusMinusPosition(String displayName)
		{
			this.displayName = displayName;
		}

		@Override
		public String toString()
		{
			return displayName;
		}
	}

	@ConfigSection(
		name = "Duplicate timers",
		description = "RuneLite indicators that can overlap Ring of Time.",
		position = 0,
		closedByDefault = true
	)
	String DUPLICATE_TIMERS_SECTION = "duplicateTimers";

	@ConfigSection(
		name = "Labels & icons",
		description = "Countdown, +/- text, and skill icon placement settings.",
		position = 1,
		closedByDefault = false
	)
	String LABELS_SECTION = "labels";

	@ConfigSection(
		name = "Ring style",
		description = "Shared ring dimensions, background, and outline settings.",
		position = 2,
		closedByDefault = false
	)
	String RING_STYLE_SECTION = "ringStyle";

	@ConfigSection(
		name = "Ring groups",
		description = "Spacing between rings joined into the same group.",
		position = 3,
		closedByDefault = false
	)
	String RING_GROUPS_SECTION = "ringGroups";

	@ConfigSection(
		name = "Buffs",
		description = "Settings for levels above their base value.",
		position = 4,
		closedByDefault = false
	)
	String BUFFS_SECTION = "buffs";

	@ConfigSection(
		name = "Individual buff colors",
		description = "Individual colors used by positive skill buffs.",
		position = 5,
		closedByDefault = true
	)
	String BUFF_COLORS_SECTION = "buffColors";

	@ConfigSection(
		name = "Debuffs",
		description = "Skill drains plus poison and venom timers.",
		position = 6,
		closedByDefault = false
	)
	String DEBUFFS_SECTION = "debuffs";

	@ConfigSection(
		name = "Protection & effect timers",
		description = "Antipoison, stamina, antifire, prayer regeneration, and thrall settings.",
		position = 7,
		closedByDefault = false
	)
	String EFFECTS_SECTION = "effects";

	@ConfigItem(
		keyName = "duplicateSkillIndicatorNotice",
		name = "<html>Boosts Information:<br>"
			+ "- Set Next buff/debuff change to Never<br>"
			+ "- Disable its infoboxes or panel if desired</html>",
		description = "Informational only; Ring of Time does not change other plugin settings.",
		position = 0,
		section = DUPLICATE_TIMERS_SECTION
	)
	default void duplicateSkillIndicatorNotice()
	{
	}

	@ConfigItem(
		keyName = "duplicateEffectIndicatorNotice",
		name = "<html>Timers & Buffs:<br>"
			+ "- Disable Antipoison, Stamina, Antifire, and Divine potion<br>"
			+ "- Poison: disable Show infoboxes</html>",
		description = "Informational only; Ring of Time does not change other plugin settings.",
		position = 1,
		section = DUPLICATE_TIMERS_SECTION
	)
	default void duplicateEffectIndicatorNotice()
	{
	}

	@ConfigItem(
		keyName = "trackedSkills",
		name = "Shown buffs",
		description = "Choose which positive temporary skill changes to display.",
		position = 0,
		section = BUFFS_SECTION
	)
	default TrackedSkills trackedSkills()
	{
		return TrackedSkills.ALL;
	}

	@ConfigItem(
		keyName = "timerPosition",
		name = "Timer position",
		description = "Place the countdown at the top, middle, or bottom of the ring, or hide it.",
		position = 0,
		section = LABELS_SECTION
	)
