import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.Rectangle;
import java.awt.geom.Arc2D;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.FontManager;

/**
 * Renders exactly one independently draggable skill timer.
 *
 * <p>The thick outer ring shows total time until this skill returns to its base
 * level. For a multi-level buff or debuff, the optional thin inner ring shows
 * the time until its next one-level change.</p>
 */
final class SkillTimerOverlay extends TimerCircleOverlay
{
	private static final int ARC_START_DEGREES = 90;
	private static final int TEXT_SHADOW_OFFSET = 1;
	private static final Color DIVINE_INDICATOR_COLOR = new Color(130, 235, 255, 245);
	private static final Color DIVINE_INDICATOR_OUTLINE_COLOR = new Color(0, 0, 0, 210);

	private final Client client;
	private final RingOfTimePlugin plugin;
	private final RingOfTimeConfig config;
	private final SkillIconManager skillIconManager;
	private final Skill skill;

	/**
	 * Creates one overlay entity for one skill. The plugin constructs all
	 * instances explicitly so each can have a distinct persistent overlay name.
	 */
	SkillTimerOverlay(
		Client client,
		RingOfTimePlugin plugin,
		RingOfTimeConfig config,
		SkillIconManager skillIconManager,
		Skill skill)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.skillIconManager = skillIconManager;
		this.skill = skill;

	}

	@Override
	public String getName()
	{
		return persistentName(skill.getName());
	}

	/**
	 * Draws this skill only, or remains absent while its timer is inactive.
	 *
	 * @return this circle's bounds, or {@code null} when it should not appear
	 */
	@Override
	public Dimension render(Graphics2D graphics)
	{
		final StatChangeTracker tracker = plugin.getTracker();
		final DivineTimerTracker divineTracker = plugin.getDivineTracker();
		final int delta = tracker.getDelta(skill);
		final boolean divine = isPositiveDivineBuff(delta, divineTracker.isActive(skill));
		if (!isTimerActive())
		{
			return null;
		}

		final int ringSize = config.ringSize();
		final int currentTick = client.getTickCount();
		final double subTickProgress = plugin.getSubTickProgress();
		final long nowMillis = System.currentTimeMillis();
		final int remainingSeconds = divine
			? divineTracker.getRemainingSeconds(skill, nowMillis)
			: tracker.getRemainingSeconds(
				skill,
				currentTick,
				subTickProgress,
				plugin.isPreserveActive()
			);
		final TimerPosition timerPosition = config.timerPosition();
		final String timeText = !timerPosition.isShown()
			? null
			: formatDuration(remainingSeconds);
		final LevelDisplay levelDisplay = divine || delta > 0
			? config.buffLevelDisplay()
			: config.debuffLevelDisplay();
		final PlusMinusPosition plusMinusPosition = divine || delta > 0
			? config.buffPlusMinusPosition()
			: config.debuffPlusMinusPosition();
		final String plusMinusText = plusMinusPosition == PlusMinusPosition.OFF
			? null
			: levelDisplay == LevelDisplay.TOTAL_LEVEL
				? Integer.toString(client.getBoostedSkillLevel(skill))
				: formatDelta(delta);
		final Font plusMinusFont = FontManager.getRunescapeBoldFont().deriveFont((float) config.plusMinusFontSize());
		final InnerRingDisplay innerRingDisplay = divine || delta > 0
			? config.buffInnerRing()
			: config.debuffInnerRing();
		final boolean innerRingVisible = !divine
			&& Math.abs(delta) > 1
			&& innerRingDisplay.isShown();
		final int thickness = Math.min(config.ringThickness(), Math.max(2, ringSize / 3));
		final int outlineThickness = config.showRingOutline() ? config.outlineThickness() : 0;
		final int clearCenterSize = TimerLabelLayout.getClearCenterSize(
			ringSize,
			thickness,
			outlineThickness,
			innerRingVisible
		);
		final Font preferredTimerFont = FontManager.getRunescapeBoldFont()
			.deriveFont((float) config.timerFontSize());
		final Font timerFont = TimerLabelLayout.fitTimerFont(
			graphics,
			preferredTimerFont,
			timeText,
			clearCenterSize
		);
		final TimerLabelLayout labelLayout = TimerLabelLayout.create(
			ringSize,
			graphics.getFontMetrics(timerFont),
			timeText,
			timerPosition,
			graphics.getFontMetrics(plusMinusFont),
			plusMinusText,
			plusMinusPosition,
			config.iconPosition()
		);

		/*
		 * A child graphics context contains our translation, antialiasing, stroke,
		 * and font changes so they cannot affect RuneLite or another overlay.
		 */
		final Graphics2D canvas = (Graphics2D) graphics.create();
		try
		{
			canvas.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			canvas.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			canvas.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
			canvas.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);
			canvas.translate(labelLayout.getRingX(), labelLayout.getRingY());

			drawTimer(
				canvas,
				delta,
				divine,
				ringSize,
				currentTick,
				subTickProgress,
				nowMillis,
				remainingSeconds,
				timeText,
				plusMinusText,
				timerFont,
				plusMinusFont,
				labelLayout
			);
		}
		finally
		{
			canvas.dispose();
		}

		return labelLayout.getDimension();
	}

	/**
	 * Draws the total ring, optional next-change ring, positioned icon, and labels.
	 */
	private void drawTimer(
		Graphics2D graphics,
		int delta,
		boolean divine,
		int size,
		int currentTick,
		double subTickProgress,
		long nowMillis,
		int remainingSeconds,
		String timeText,
		String plusMinusText,
		Font timerFont,
		Font plusMinusFont,
		TimerLabelLayout labelLayout)
	{
		final StatChangeTracker tracker = plugin.getTracker();
		final double totalProgress = divine
			? plugin.getDivineTracker().getProgress(skill, nowMillis)
			: tracker.getOverallProgress(skill, currentTick, subTickProgress);
		final int thickness = Math.min(config.ringThickness(), Math.max(2, size / 3));
		final int outlineThickness = config.showRingOutline() ? config.outlineThickness() : 0;
		final double edgeMargin = Math.max(1d, outlineThickness);
		final double inset = thickness / 2d + edgeMargin;
		final double diameter = size - thickness - edgeMargin * 2d;
		final Arc2D.Double ring = new Arc2D.Double(
			inset,
			inset,
			diameter,
			diameter,
			ARC_START_DEGREES,
			-360d,
			Arc2D.OPEN
		);
		final Color outlineColor = divine || delta > 0
			? config.buffOutlineColor()
			: config.debuffOutlineColor();
		final Color innerRingColor = divine || delta > 0
			? config.buffInnerRingColor()
			: config.debuffInnerRingColor();

		if (config.showRingOutline())
		{
			graphics.setStroke(new BasicStroke(
				thickness + outlineThickness * 2,
				BasicStroke.CAP_ROUND,
				BasicStroke.JOIN_ROUND
			));
			graphics.setColor(outlineColor);
			graphics.draw(ring);
		}

		graphics.setStroke(new BasicStroke(thickness, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		graphics.setColor(config.emptyRingColor());
		graphics.draw(ring);

		final Color activeColor = divine || delta > 0
			? (config.useBaseBuffColor() ? config.buffColor() : SkillColorPalette.getColor(skill, config))
			: config.debuffColor();
		ring.setAngleExtent(-360d * totalProgress);
		graphics.setColor(activeColor);
		graphics.draw(ring);

		if (divine || delta > 0)
		{
			drawExpiryFlash(
				graphics,
				ring,
				thickness,
				activeColor,
				remainingSeconds,
				currentTick,
				subTickProgress
			);
		}
		if (divine)
		{
			drawDivineIndicator(graphics, size, thickness, outlineThickness);
		}

		final InnerRingDisplay innerRingDisplay = divine || delta > 0
			? config.buffInnerRing()
			: config.debuffInnerRing();
		if (!divine && Math.abs(delta) > 1 && innerRingDisplay.isShown())
		{
			drawNextLevelIndicator(
				graphics,
				size,
				thickness,
				outlineThickness,
				tracker.getNextChangeProgress(skill, currentTick, subTickProgress),
				innerRingColor,
				outlineColor
			);
		}

		drawSkillIcon(graphics, labelLayout.getIconBounds());
		final Color timerTextColor = getTimerTextColor(
			delta,
			plugin.isPreserveActive() && !divine
		);
		drawLabel(
			graphics,
			timeText,
			labelLayout.getTimerBounds(),
			timerTextColor,
			timerFont,
			false
		);
		final Color plusMinusColor = divine || delta > 0
			? config.buffPlusMinusColor()
			: config.debuffPlusMinusColor();
		drawLabel(
			graphics,
			plusMinusText,
			labelLayout.getPlusMinusBounds(),
			plusMinusColor,
			plusMinusFont,
			true
		);
	}
	/**
	 * Marks a fixed-duration divine potion with a small crystalline diamond at
	 * the top of the ring without replacing that skill's configured color.
	 */
	private static void drawDivineIndicator(
		Graphics2D graphics,
		int size,
		int ringThickness,
		int outlineThickness)
	{
		final Polygon marker = createDivineIndicator(size, ringThickness, outlineThickness);
		graphics.setColor(DIVINE_INDICATOR_COLOR);
		graphics.fillPolygon(marker);
		graphics.setStroke(new BasicStroke(1f));
		graphics.setColor(DIVINE_INDICATOR_OUTLINE_COLOR);
		graphics.drawPolygon(marker);
	}

	/**
	 * Builds a compact marker centered on the outer ring's twelve-o'clock point.
	 */
	static Polygon createDivineIndicator(int size, int ringThickness, int outlineThickness)
	{
		final int halfWidth = Math.max(2, Math.min(4, (ringThickness + 1) / 2));
		final int halfHeight = halfWidth + 1;
		final int centerX = size / 2;
		final int centerY = Math.max(
			halfHeight,
			(int) Math.round(Math.max(1d, outlineThickness) + ringThickness / 2d)
		);
		return new Polygon(
			new int[]{centerX, centerX + halfWidth, centerX, centerX - halfWidth},
			new int[]{centerY - halfHeight, centerY, centerY + halfHeight, centerY},
			4
		);
	}

	/**
	 * Flashes a complete ring in its own configured color near beneficial expiry.
	 * Game-tick time keeps the pulse deterministic and independent of frame rate.
	 */
	private void drawExpiryFlash(
		Graphics2D graphics,
		Arc2D.Double ring,
		int thickness,
		Color color,
		int remainingSeconds,
		int currentTick,
		double subTickProgress)
	{
		if (!config.flashExpiringBuffs()
			|| remainingSeconds <= 0
			|| remainingSeconds > config.flashThresholdSeconds())
		{
			return;
		}

		final long elapsedMillis = Math.round(
			(currentTick + subTickProgress) * net.runelite.api.Constants.GAME_TICK_LENGTH
		);
		final boolean brightPhase = (elapsedMillis / 300L) % 2L == 0L;
		final int pulseAlpha = Math.min(color.getAlpha(), brightPhase ? 235 : 55);
		ring.setAngleExtent(-360d);
		graphics.setStroke(new BasicStroke(thickness, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), pulseAlpha));
		graphics.draw(ring);
	}

	/**
	 * Draws the thin countdown to the next one-level buff or debuff change.
	 */
	private void drawNextLevelIndicator(
		Graphics2D graphics,
		int size,
		int outerThickness,
		int outlineThickness,
		double progress,
		Color innerRingColor,
		Color outlineColor)
	{
		final int innerThickness = Math.max(2, Math.min(4, (outerThickness + 1) / 2));
		final double gap = Math.max(2d, outerThickness * 0.35d);
		final double edgeMargin = Math.max(1d, outlineThickness);
		final double inset = outerThickness
			+ edgeMargin
			+ outlineThickness
			+ gap
			+ innerThickness / 2d;
		final double diameter = size - inset * 2d;

		// Very small, unusually thick rings may not have safe room for a second arc.
		if (diameter < 10d)
		{
			return;
		}

		final Arc2D.Double nextLevelRing = new Arc2D.Double(
			inset,
			inset,
			diameter,
			diameter,
			ARC_START_DEGREES,
			-360d,
			Arc2D.OPEN
		);
		if (config.showRingOutline())
		{
			graphics.setStroke(new BasicStroke(
				innerThickness + outlineThickness * 2,
				BasicStroke.CAP_ROUND,
				BasicStroke.JOIN_ROUND
			));
			graphics.setColor(outlineColor);
			graphics.draw(nextLevelRing);
		}

		graphics.setStroke(new BasicStroke(innerThickness, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		graphics.setColor(withReducedAlpha(config.emptyRingColor()));
		graphics.draw(nextLevelRing);

		nextLevelRing.setAngleExtent(-360d * progress);
		graphics.setColor(innerRingColor);
		graphics.draw(nextLevelRing);
	}

	private void drawSkillIcon(Graphics2D graphics, Rectangle bounds)
	{
		final Image icon = skillIconManager.getSkillImage(skill);
		if (icon == null)
		{
			return;
		}

		final int sourceWidth = Math.max(1, icon.getWidth(null));
		final int sourceHeight = Math.max(1, icon.getHeight(null));
		final double scale = Math.min(
			1d,
			Math.min(bounds.width / (double) sourceWidth, bounds.height / (double) sourceHeight)
		);
		final int iconWidth = Math.max(1, (int) Math.round(sourceWidth * scale));
		final int iconHeight = Math.max(1, (int) Math.round(sourceHeight * scale));
		final int iconX = bounds.x + (bounds.width - iconWidth) / 2;
		final int iconY = bounds.y + (bounds.height - iconHeight) / 2;

		graphics.drawImage(icon, iconX, iconY, iconWidth, iconHeight, null);
	}

	/**
	 * Draws fitted timer text without a background, or a +/- value with its
	 * configurable badge background.
	 */
	private void drawLabel(
		Graphics2D graphics,
		String text,
		Rectangle bounds,
		Color textColor,
		Font font,
		boolean drawBackground)
	{
		if (text == null || bounds == null)
		{
			return;
		}

		final FontMetrics metrics = graphics.getFontMetrics(font);
		final int textX = bounds.x + (bounds.width - metrics.stringWidth(text)) / 2;
		final int baselineY = bounds.y + (bounds.height - metrics.getHeight()) / 2
			+ metrics.getAscent();

		if (drawBackground)
		{
			graphics.setColor(config.plusMinusBackgroundColor());
			graphics.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 6, 6);
		}
		graphics.setFont(font);
		graphics.setColor(new Color(0, 0, 0, 235));
		graphics.drawString(
			text,
			textX + TEXT_SHADOW_OFFSET,
			baselineY + TEXT_SHADOW_OFFSET
		);
		graphics.setColor(textColor);
		graphics.drawString(text, textX, baselineY);
	}

	/**
	 * Includes this skill in automatic stacking only while it is visible and
	 * differs from its real level.
	 */
	@Override
	boolean isTimerActive()
	{
		final int delta = plugin.getTracker().getDelta(skill);
		if (!plugin.isSkillVisible(skill))
		{
			return false;
		}

		return delta > 0
			|| (delta < 0 && config.debuffDisplay().showsSkills());
	}

	static boolean isPositiveDivineBuff(int delta, boolean divineTimerActive)
	{
		return delta > 0 && divineTimerActive;
	}

	/**
	 * Uses cyan only while Preserve can extend an active positive skill buff.
	 * Re-evaluating this every frame restores white as soon as Preserve turns off.
	 */
	static Color getTimerTextColor(int delta, boolean preserveActive)
	{
		return delta > 0 && preserveActive ? Color.CYAN : Color.WHITE;
	}

	/**
	 * Makes the inner ring's unused track quieter than the primary outer track.
	 */
	private static Color withReducedAlpha(Color color)
	{
		return new Color(
			color.getRed(),
			color.getGreen(),
			color.getBlue(),
			Math.max(30, color.getAlpha() / 2)
		);
	}

	/**
	 * Formats long countdowns compactly enough to fit inside or below the ring.
	 */
	private static String formatDuration(int totalSeconds)
	{
		if (totalSeconds < 60)
		{
			return totalSeconds + "s";
		}

		final int minutes = totalSeconds / 60;
		final int seconds = totalSeconds % 60;
		return minutes + ":" + (seconds < 10 ? "0" : "") + seconds;
	}

	/**
	 * Makes positive and negative changes visually unambiguous.
	 */
	private static String formatDelta(int delta)
	{
		return delta > 0 ? "+" + delta : Integer.toString(delta);
	}
}

package com.ringoftime;

import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.Set;
import net.runelite.api.Constants;
import net.runelite.api.Skill;

/**
 * Tracks temporary skill changes independently from RuneLite's rendering code.
 *
 * <p>Old School RuneScape restores boosted stats downward and drained stats
 * upward on separate shared clocks. A natural one-level change reveals the
 * exact phase of its clock. Until that happens, this tracker starts a local
 * estimate so the user still gets an immediately useful visual.</p>
 *
 * <p>The overall progress for a skill combines its current level difference
 * with the fractional progress of the current shared clock cycle. This makes
 * the annulus shrink continuously across each one-level transition.</p>
 */
final class StatChangeTracker
{
	static final int NORMAL_CYCLE_TICKS = 100;
	static final int PRESERVE_CYCLE_TICKS = 150;

	private static final int UNKNOWN_DELTA = Integer.MIN_VALUE;

	private final int[] lastDeltas = new int[Skill.values().length];
	private final int[] peakMagnitudes = new int[Skill.values().length];
	private final boolean[] fixedDurationBuffs = new boolean[Skill.values().length];
	private final EnumSet<Skill> activeSkills = EnumSet.noneOf(Skill.class);
	private final Set<Skill> readOnlyActiveSkills = Collections.unmodifiableSet(activeSkills);
	private final CycleTimer buffCycle = new CycleTimer(true);
	private final CycleTimer debuffCycle = new CycleTimer(false);

	StatChangeTracker()
	{
		reset();
	}

	/**
	 * Clears all learned levels and timer phases, such as after a logout or hop.
	 */
	void reset()
	{
		Arrays.fill(lastDeltas, UNKNOWN_DELTA);
		Arrays.fill(peakMagnitudes, 0);
		Arrays.fill(fixedDurationBuffs, false);
		activeSkills.clear();
		buffCycle.stop();
		debuffCycle.stop();
	}

	/**
	 * Observes the latest levels for one skill and updates its timer state.
	 *
	 * @param skill skill whose level changed or was sampled
	 * @param boostedLevel current effective level reported by the client
	 * @param realLevel base level reported by the client
	 * @param currentTick RuneLite game-tick counter at the observation time
	 */
	void observe(Skill skill, int boostedLevel, int realLevel, int currentTick)
	{
		observe(skill, boostedLevel, realLevel, currentTick, false);
	}

	/**
	 * Observes a skill while excluding fixed-duration divine boosts from the
	 * ordinary shared stat-restoration clock.
	 */
	void observe(
		Skill skill,
		int boostedLevel,
		int realLevel,
		int currentTick,
		boolean fixedDurationBuff)
	{
		final int index = skill.ordinal();
		final int previousDelta = lastDeltas[index];
		final boolean wasFixedDuration = fixedDurationBuffs[index];
		final int delta = boostedLevel - realLevel;

		/*
		 * A one-level move toward zero is the normal restoration event. It
		 * provides an exact anchor for the appropriate shared stat clock.
		 */
		if (!wasFixedDuration && !fixedDurationBuff
			&& previousDelta > 0 && delta == previousDelta - 1)
		{
			buffCycle.synchronize(currentTick);
		}
		else if (previousDelta < 0 && delta == previousDelta + 1)
		{
			debuffCycle.synchronize(currentTick);
		}

		if (delta == 0)
		{
			// Returning to the real level removes the skill's visual entirely.
			activeSkills.remove(skill);
			peakMagnitudes[index] = 0;
		}
		else
		{
			final int magnitude = Math.abs(delta);

			/*
			 * A new effect or a direction change starts a fresh visual. A
			 * stronger re-boost/re-drain expands the visual's reference size.
			 */
			if (previousDelta == UNKNOWN_DELTA
				|| previousDelta == 0
				|| Integer.signum(previousDelta) != Integer.signum(delta))
			{
				peakMagnitudes[index] = magnitude;
			}
			else
			{
				peakMagnitudes[index] = Math.max(peakMagnitudes[index], magnitude);
			}

			activeSkills.add(skill);

			/*
			 * The first cycle is estimated because the server does not expose
			 * its current stat-clock phase. A natural restoration later syncs it.
			 */
			if (delta < 0 || !fixedDurationBuff)
			{
				cycleFor(delta).startEstimatedIfStopped(currentTick);
			}
		}

		fixedDurationBuffs[index] = fixedDurationBuff && delta > 0;
		lastDeltas[index] = delta;

		// Do not carry an obsolete clock into a future, unrelated effect.
		if (!hasDirection(true))
		{
			buffCycle.stop();
		}
		if (!hasDirection(false))
		{
			debuffCycle.stop();
		}
	}

	/**
	 * Advances shared clocks and applies Preserve's current extension state.
	 *
	 * @param currentTick current RuneLite game tick
	 * @param preserveActive whether the Preserve prayer is currently active
	 */
	void onGameTick(int currentTick, boolean preserveActive)
	{
		if (hasDirection(true))
		{
			buffCycle.onGameTick(currentTick, preserveActive);
		}
		if (hasDirection(false))
		{
			debuffCycle.onGameTick(currentTick, false);
		}
	}

	/**
	 * Returns a read-only live view of skills that differ from their base level.
	 */
	Set<Skill> getActiveSkills()
	{
		return readOnlyActiveSkills;
	}

	/**
	 * Returns the signed effective-level difference for a skill.
	 */
	int getDelta(Skill skill)
	{
		final int delta = lastDeltas[skill.ordinal()];
		return delta == UNKNOWN_DELTA ? 0 : delta;
	}

	/**
	 * Calculates the fraction of the complete effect that remains.
	 *
	 * @param skill active skill to inspect
	 * @param currentTick current RuneLite game tick
	 * @param subTickProgress fraction from the latest game tick to the next
	 * @return value clamped to the inclusive range {@code [0, 1]}
	 */
	double getOverallProgress(Skill skill, int currentTick, double subTickProgress)
	{
		final int delta = getDelta(skill);
		if (delta == 0)
		{
			return 0d;
		}

		final int magnitude = Math.abs(delta);
		final int peak = Math.max(magnitude, peakMagnitudes[skill.ordinal()]);
		final double cycleProgress = cycleFor(delta).getProgress(currentTick, subTickProgress);

		/*
		 * Completed level cycles count as whole units; the current cycle is the
		 * fractional unit. This keeps the arc continuous at restoration ticks.
		 */
		final double overall = (magnitude - 1d + cycleProgress) / peak;
		return clamp(overall);
	}

	/**
	 * Calculates the fraction remaining until the next one-level change.
	 *
	 * <p>The overlay uses this separate progress value for its thin inner
	 * annulus. Unlike {@link #getOverallProgress(Skill, int, double)}, it
	 * returns to a full circle after each natural level restoration.</p>
	 *
	 * @param skill active skill to inspect
	 * @param currentTick current RuneLite game tick
	 * @param subTickProgress fraction from the latest game tick to the next
	 * @return current shared-cycle progress in the range {@code [0, 1]}
	 */
	double getNextChangeProgress(Skill skill, int currentTick, double subTickProgress)
	{
		final int delta = getDelta(skill);
		return delta == 0
			? 0d
			: cycleFor(delta).getProgress(currentTick, subTickProgress);
	}

	/**
	 * Projects seconds until the skill reaches its real level.
	 *
	 * <p>Future Preserve use cannot be known, so future buff cycles assume the
	 * prayer remains in its current state.</p>
	 */
	int getRemainingSeconds(
		Skill skill,
		int currentTick,
		double subTickProgress,
		boolean preserveActive)
	{
		final int delta = getDelta(skill);
		if (delta == 0)
		{
			return 0;
		}

		final CycleTimer cycle = cycleFor(delta);
		final int magnitude = Math.abs(delta);
		final double currentCycleTicks = cycle.getRemainingTicks(currentTick, subTickProgress);
		final int projectedCycleTicks = delta > 0 && preserveActive
			? PRESERVE_CYCLE_TICKS
			: NORMAL_CYCLE_TICKS;
		final double totalTicks = currentCycleTicks + (magnitude - 1d) * projectedCycleTicks;

		return (int) Math.ceil(totalTicks * Constants.GAME_TICK_LENGTH / 1000d);
	}

	/**
	 * Reports whether the selected skill still uses an estimated clock phase.
	 */
	boolean isEstimated(Skill skill)
	{
		final int delta = getDelta(skill);
		return delta != 0 && cycleFor(delta).isEstimated();
	}

	/**
	 * Selects the independent buff or debuff restoration clock.
	 */
	private CycleTimer cycleFor(int delta)
	{
		return delta > 0 ? buffCycle : debuffCycle;
	}

	/**
	 * Checks whether any active skill currently uses the requested direction.
	 */
	private boolean hasDirection(boolean buff)
	{
		for (Skill skill : activeSkills)
		{
			final int delta = getDelta(skill);
			if ((buff && delta > 0 && !fixedDurationBuffs[skill.ordinal()])
				|| (!buff && delta < 0))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Clamps floating-point rounding at the start and end of an animation.
	 */
	private static double clamp(double value)
	{
		return Math.max(0d, Math.min(1d, value));
	}

	/**
	 * Models one of RuneScape's two shared stat-restoration clocks.
	 */
	private static final class CycleTimer
	{
		private final boolean buff;
		private int startTick = -1;
		private int cycleLengthTicks = NORMAL_CYCLE_TICKS;
		private boolean estimated = true;
		private boolean preserveWasActiveInExtensionWindow;

		private CycleTimer(boolean buff)
		{
			this.buff = buff;
		}

		/**
		 * Starts a best-effort clock only when no clock is currently running.
		 */
		private void startEstimatedIfStopped(int currentTick)
		{
			if (startTick == -1)
			{
				restart(currentTick, true);
			}
		}

		/**
		 * Anchors the next cycle to an observed natural restoration tick.
		 */
		private void synchronize(int currentTick)
		{
			restart(currentTick, false);
		}

		/**
		 * Updates Preserve timing and rolls over a cycle if its event was missed.
		 */
		private void onGameTick(int currentTick, boolean preserveActive)
		{
			if (startTick == -1)
			{
				return;
			}

			final int elapsedTicks = Math.max(0, currentTick - startTick);

			if (buff)
			{
				/*
				 * This mirrors RuneLite's boost-clock model. Preserve can extend
				 * the normal 100-tick cycle to 125 or 150 ticks depending on the
				 * portion of the cycle during which it remains active.
				 */
				final boolean useFullExtension =
					(preserveActive && (elapsedTicks < 75 || preserveWasActiveInExtensionWindow))
						|| elapsedTicks > 125;

				if (useFullExtension)
				{
					preserveWasActiveInExtensionWindow = true;
					cycleLengthTicks = PRESERVE_CYCLE_TICKS;
				}
				else
				{
					preserveWasActiveInExtensionWindow = false;
					cycleLengthTicks = elapsedTicks > 100 ? 125 : NORMAL_CYCLE_TICKS;
				}
			}
			else
			{
				// Drained stats always restore on the normal 100-tick cycle.
				cycleLengthTicks = NORMAL_CYCLE_TICKS;
			}

			if (elapsedTicks >= cycleLengthTicks)
			{
				/*
				 * Missing the server event means the new phase is uncertain.
				 * Restart visibly, but mark it estimated until an event syncs it.
				 */
				restart(currentTick, true);
			}
		}

		/**
		 * Returns the remaining fraction of the current level-change cycle.
		 */
		private double getProgress(int currentTick, double subTickProgress)
		{
			if (startTick == -1)
			{
				return 0d;
			}
			return clamp(getRemainingTicks(currentTick, subTickProgress) / cycleLengthTicks);
		}

		/**
		 * Returns smooth, fractional ticks left in the current cycle.
		 */
		private double getRemainingTicks(int currentTick, double subTickProgress)
		{
			if (startTick == -1)
			{
				return 0d;
			}

			final double elapsed = Math.max(0d, currentTick - startTick + clamp(subTickProgress));
			return Math.max(0d, cycleLengthTicks - elapsed);
		}

		private boolean isEstimated()
		{
			return estimated;
		}

		/**
		 * Stops the clock and removes all Preserve history.
		 */
		private void stop()
		{
			startTick = -1;
			cycleLengthTicks = NORMAL_CYCLE_TICKS;
			estimated = true;
			preserveWasActiveInExtensionWindow = false;
		}

		/**
		 * Initializes a new cycle with a known or estimated phase.
		 */
		private void restart(int currentTick, boolean estimated)
		{
			startTick = currentTick;
			cycleLengthTicks = NORMAL_CYCLE_TICKS;
			this.estimated = estimated;
			preserveWasActiveInExtensionWindow = false;
		}
	}
}

package com.ringoftime;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

/**
 * Adapts one timer ring to RuneLite's wrapping panel-component API.
 */
final class TimerCircleComponent implements LayoutableRenderableEntity
{
	private final TimerCircleOverlay timer;
	private final Rectangle bounds = new Rectangle();
	private Point preferredLocation = new Point();
	private Dimension preferredSize = new Dimension();

	TimerCircleComponent(TimerCircleOverlay timer)
	{
		this.timer = timer;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final Graphics2D canvas = (Graphics2D) graphics.create();
		try
		{
			canvas.translate(preferredLocation.x, preferredLocation.y);
			final Dimension timerSize = timer.render(canvas);
			if (timerSize == null)
			{
				bounds.setBounds(preferredLocation.x, preferredLocation.y, 0, 0);
				return new Dimension();
			}

			bounds.setBounds(
				preferredLocation.x,
				preferredLocation.y,
				timerSize.width,
				timerSize.height
			);
			return new Dimension(bounds.width, bounds.height);
		}
		finally
		{
			canvas.dispose();
		}
	}

	TimerCircleOverlay getTimer()
	{
		return timer;
	}

	@Override
	public Rectangle getBounds()
	{
		return bounds;
	}

	@Override
	public void setPreferredLocation(Point position)
	{
		preferredLocation = position == null ? new Point() : new Point(position);
	}

	@Override
	public void setPreferredSize(Dimension dimension)
	{
		// Wrapping is based on the timer's rendered bounds, not padded cells.
	}
}

package com.ringoftime;

import java.awt.Point;

/**
 * Pure vertical layout calculation for active circles that have not been
 * manually dragged.
 */
final class TimerCircleLayout
{
	private static final int ORIGIN_X = 10;
	private static final int ORIGIN_Y = 10;
	private static final int GAP = 4;

	private TimerCircleLayout()
	{
		// Utility class.
	}

	/**
	 * Returns the top-left point for one active circle in the vertical stack.
	 */
	static Point getLocation(int activeIndex, int circleHeight)
	{
		final int safeIndex = Math.max(0, activeIndex);
		return new Point(ORIGIN_X, ORIGIN_Y + safeIndex * (circleHeight + GAP));
	}
}

package com.ringoftime;

import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.Overlay;

/**
 * Base renderable entity shared by skill and effect timer rings. Group
 * overlays own movement, resizing, wrapping, and persisted placement.
 */
abstract class TimerCircleOverlay extends Overlay
{
	private static final String PERSISTENT_NAME_PREFIX = "Ring of Time - ";

	TimerCircleOverlay(Plugin plugin)
	{
		super(plugin);
	}

	static String persistentName(String label)
	{
		return PERSISTENT_NAME_PREFIX + label.replace(':', '-');
	}

	/**
	 * Reports whether this timer should be included in its active group layout.
	 */
	abstract boolean isTimerActive();
}

package com.ringoftime;

import com.google.gson.Gson;
import java.awt.Dimension;
import java.awt.Point;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.components.ComponentOrientation;

/**
 * Owns ring-group membership, overlay registration, and saved layout metadata.
 */
final class TimerGroupManager
{
	private static final String LAYOUT_CONFIG_GROUP = "ring-of-time-layout";
	private static final String MEMBER_PREFIX = "member_";
	private static final String ORIENTATION_PREFIX = "orientation_";
	private static final String ORDER_PREFIX = "order_";
	private static final String SIZE_PREFIX = "size_";
	private static final String NEXT_GROUP_NUMBER_KEY = "nextGroupNumber";
	private static final String ORDER_SEPARATOR = "\n";
	private static final int DETACH_OFFSET = 16;
	private static final String RUNELITE_CONFIG_GROUP = "runelite";
	private static final String[] OVERLAY_CONFIG_SUFFIXES =
	{
		"_preferredLocation",
		"_preferredPosition",
		"_origin",
		"_originX",
		"_originY",
		"_preferredSize"
	};

	private final Client client;
	private final RingOfTimePlugin plugin;
	private final RingOfTimeConfig config;
	private final OverlayManager overlayManager;
	private final ConfigManager configManager;
	private final CustomUiAnchorsCompatibility customUiAnchorsCompatibility;

	private final Map<String, TimerGroupOverlay> groups = new LinkedHashMap<>();

	TimerGroupManager(
		Client client,
		RingOfTimePlugin plugin,
		RingOfTimeConfig config,
		OverlayManager overlayManager,
		ConfigManager configManager,
		Gson gson)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.overlayManager = overlayManager;
		this.configManager = configManager;
		this.customUiAnchorsCompatibility = new CustomUiAnchorsCompatibility(configManager, gson);
	}

	void start(Collection<? extends TimerCircleOverlay> timers)
	{
		final Map<String, List<TimerCircleOverlay>> membersByGroup = new LinkedHashMap<>();
		for (TimerCircleOverlay timer : timers)
		{
			final String savedGroup = getSavedGroup(timer);
			final String groupName = savedGroup == null ? timer.getName() : savedGroup;
			membersByGroup.computeIfAbsent(groupName, ignored -> new ArrayList<>()).add(timer);
		}

		final Set<String> reservedNames = new HashSet<>(membersByGroup.keySet());
		for (Map.Entry<String, List<TimerCircleOverlay>> entry : membersByGroup.entrySet())
		{
			String groupName = entry.getKey();
			final List<TimerCircleOverlay> members = entry.getValue();
			if (isMemberNamedGroup(groupName, members) && members.size() > 1)
			{
				final String independentName = createIndependentGroupName(reservedNames);
				migrateSavedGroup(groupName, independentName, members);
				groupName = independentName;
				reservedNames.add(independentName);
			}

			final TimerGroupOverlay group = createGroup(groupName);
			for (TimerCircleOverlay member : members)
			{
				group.addMember(member);
			}
		}

		for (TimerGroupOverlay group : groups.values())
		{
			group.restoreMemberOrder(loadOrder(group.getName()));
		}
		customUiAnchorsCompatibility.reconcile(groups.values());
	}

	void shutDown()
	{
		for (TimerGroupOverlay group : groups.values())
		{
			rememberSize(group);
			overlayManager.saveOverlay(group);
			overlayManager.remove(group);
		}
		groups.clear();
	}

	boolean merge(TimerGroupOverlay source, TimerGroupOverlay destination)
	{
		if (source == destination
			|| !groups.containsValue(source)
			|| !groups.containsValue(destination))
		{
			return false;
		}

		if (isMemberNamedGroup(destination.getName(), destination.getMembers()))
		{
			destination = promoteToIndependentGroup(destination);
		}

		destination.markManaged();
		for (TimerCircleOverlay timer : source.getMembers())
		{
			source.removeMember(timer);
			destination.addMember(timer);
			saveGroup(timer, destination.getName());
		}

		groups.remove(source.getName());
		overlayManager.remove(source);
		saveOrder(destination);
		customUiAnchorsCompatibility.merge(source, destination);
		clearSavedGroupMetadata(source.getName());
		clearOverlayConfiguration(source.getName());
		return true;
	}

	/**
	 * Moves the selected visible ring through its group and persists the result.
	 */
	boolean reorder(
		TimerGroupOverlay group,
		TimerCircleOverlay dragged,
		TimerCircleOverlay target,
		boolean insertAfter)
	{
		if (!groups.containsValue(group)
			|| !group.moveMember(dragged, target, insertAfter))
		{
			return false;
		}

		saveOrder(group);
		return true;
	}

	/**
	 * Finds a visible ring at the supplied canvas coordinate.
	 */
	TimerGroupOverlay.MemberHit findMemberAt(Point canvasPoint)
	{
		for (TimerGroupOverlay group : groups.values())
		{
			final TimerGroupOverlay.MemberHit hit = group.findMemberAt(canvasPoint);
			if (hit != null)
			{
				return hit;
			}
		}

		return null;
	}

	void handleMenu(TimerGroupOverlay group, String option)
	{
		if (TimerGroupOverlay.DETACH_OPTION.equals(option))
		{
			detach(group, group.getHoveredTimer());
		}
		else if (TimerGroupOverlay.FLIP_OPTION.equals(option))
		{
			final ComponentOrientation orientation = group.flip();
			configManager.setConfiguration(
				LAYOUT_CONFIG_GROUP,
				ORIENTATION_PREFIX + group.getName(),
				orientation
			);
		}
	}

	List<TimerGroupOverlay> getGroups()
	{
		return new ArrayList<>(groups.values());
	}

	void handleOverlayConfigChanged(String key, String newValue)
	{
		if (newValue == null || newValue.trim().isEmpty())
		{
			return;
		}

		for (TimerGroupOverlay group : groups.values())
		{
			if ((group.getName() + "_preferredSize").equals(key))
			{
				rememberSize(group);
				return;
			}
		}
	}

	private void detach(TimerGroupOverlay source, TimerCircleOverlay timer)
	{
		if (timer == null || source.getMembers().size() <= 1)
		{
			return;
		}

		source.markManaged();
		final String groupName = groups.containsKey(timer.getName())
			? TimerCircleOverlay.persistentName("Group " + UUID.randomUUID())
			: timer.getName();
		final TimerGroupOverlay detached = createGroup(groupName);
		customUiAnchorsCompatibility.detach(groupName);

		source.removeMember(timer);
		detached.addMember(timer);
		saveGroup(timer, groupName);
		saveOrder(source);
		saveOrder(detached);
		configManager.setConfiguration(
			LAYOUT_CONFIG_GROUP,
			ORIENTATION_PREFIX + groupName,
			source.getOrientation()
		);
		if (detached.getOrientation() != source.getOrientation())
		{
			detached.flip();
		}

		final Point sourceLocation = source.getPreferredLocation() != null
			? new Point(source.getPreferredLocation())
			: source.getBounds().getLocation();
		sourceLocation.translate(DETACH_OFFSET, DETACH_OFFSET);
		detached.placeDetachedAt(sourceLocation);
		overlayManager.saveOverlay(detached);
	}

	private TimerGroupOverlay createGroup(String groupName)
	{
		ComponentOrientation orientation = configManager.getConfiguration(
			LAYOUT_CONFIG_GROUP,
			ORIENTATION_PREFIX + groupName,
			ComponentOrientation.class
		);
		if (orientation == null)
		{
			orientation = ComponentOrientation.VERTICAL;
		}

		final TimerGroupOverlay group = new TimerGroupOverlay(
			client,
			plugin,
			config,
			this,
			groupName,
			orientation
		);
		groups.put(groupName, group);
		overlayManager.add(group);

		/*
		 * External overlay managers can temporarily clear RuneLite's native size
		 * key while repositioning an overlay. Keep a plugin-owned copy so a group
		 * retains its rows and columns even if the client closes at that moment.
		 */
		final Dimension savedSize = configManager.getConfiguration(
			LAYOUT_CONFIG_GROUP,
			SIZE_PREFIX + groupName,
			Dimension.class
		);
		if (savedSize == null)
		{
			rememberSize(group);
		}
		else
		{
			group.setPreferredSize(new Dimension(savedSize));
		}

		group.initializeAutomaticLayout();
		return group;
	}

	private TimerGroupOverlay promoteToIndependentGroup(TimerGroupOverlay source)
	{
		final String groupName = createIndependentGroupName(groups.keySet());
		overlayManager.saveOverlay(source);
		moveConfiguration(SIZE_PREFIX + source.getName(), SIZE_PREFIX + groupName);
		moveOverlayConfiguration(source.getName(), groupName);
		final TimerGroupOverlay promoted = createGroup(groupName);
		promoted.markManaged();

		if (promoted.getOrientation() != source.getOrientation())
		{
			promoted.flip();
		}
		configManager.setConfiguration(
			LAYOUT_CONFIG_GROUP,
			ORIENTATION_PREFIX + groupName,
			source.getOrientation()
		);

		for (TimerCircleOverlay timer : source.getMembers())
		{
			source.removeMember(timer);
			promoted.addMember(timer);
			saveGroup(timer, groupName);
		}
		saveOrder(promoted);
		customUiAnchorsCompatibility.merge(source, promoted);

		groups.remove(source.getName());
		overlayManager.remove(source);
		clearSavedGroupMetadata(source.getName());
		clearOverlayConfiguration(source.getName());
		return promoted;
	}

	private void migrateSavedGroup(
		String oldName,
		String newName,
		Collection<TimerCircleOverlay> members)
	{
		for (TimerCircleOverlay member : members)
		{
			saveGroup(member, newName);
		}

		moveConfiguration(ORIENTATION_PREFIX + oldName, ORIENTATION_PREFIX + newName);
		moveConfiguration(ORDER_PREFIX + oldName, ORDER_PREFIX + newName);
		moveConfiguration(SIZE_PREFIX + oldName, SIZE_PREFIX + newName);
		moveOverlayConfiguration(oldName, newName);
	}

	private String createIndependentGroupName(Collection<String> reservedNames)
	{
		Integer nextNumber = configManager.getConfiguration(
			LAYOUT_CONFIG_GROUP,
			NEXT_GROUP_NUMBER_KEY,
			Integer.class
		);
		int number = nextNumber == null ? 1 : Math.max(1, nextNumber);

		String name;
		do
		{
			name = TimerCircleOverlay.persistentName("Group " + number++);
		}
		while (reservedNames.contains(name) || hasSavedGroupData(name));

		configManager.setConfiguration(LAYOUT_CONFIG_GROUP, NEXT_GROUP_NUMBER_KEY, number);
		return name;
	}

	private boolean hasSavedGroupData(String groupName)
	{
		if (configManager.getConfiguration(
			LAYOUT_CONFIG_GROUP,
			ORIENTATION_PREFIX + groupName) != null
			|| configManager.getConfiguration(
				LAYOUT_CONFIG_GROUP,
				ORDER_PREFIX + groupName) != null
			|| configManager.getConfiguration(
				LAYOUT_CONFIG_GROUP,
				SIZE_PREFIX + groupName) != null)
		{
			return true;
		}

		for (String suffix : OVERLAY_CONFIG_SUFFIXES)
		{
			if (configManager.getConfiguration(RUNELITE_CONFIG_GROUP, groupName + suffix) != null)
			{
				return true;
			}
		}
		return false;
	}

	private void moveConfiguration(String oldKey, String newKey)
	{
		final String value = configManager.getConfiguration(LAYOUT_CONFIG_GROUP, oldKey);
		if (value != null)
		{
			configManager.setConfiguration(LAYOUT_CONFIG_GROUP, newKey, value);
			configManager.unsetConfiguration(LAYOUT_CONFIG_GROUP, oldKey);
		}
	}

	private void moveOverlayConfiguration(String oldName, String newName)
	{
		for (String suffix : OVERLAY_CONFIG_SUFFIXES)
		{
			final String oldKey = oldName + suffix;
			final String value = configManager.getConfiguration(RUNELITE_CONFIG_GROUP, oldKey);
			if (value != null)
			{
				configManager.setConfiguration(RUNELITE_CONFIG_GROUP, newName + suffix, value);
				configManager.unsetConfiguration(RUNELITE_CONFIG_GROUP, oldKey);
			}
		}
	}

	private void clearOverlayConfiguration(String groupName)
	{
		for (String suffix : OVERLAY_CONFIG_SUFFIXES)
		{
			configManager.unsetConfiguration(RUNELITE_CONFIG_GROUP, groupName + suffix);
		}
	}

	private void clearSavedGroupMetadata(String groupName)
	{
		configManager.unsetConfiguration(LAYOUT_CONFIG_GROUP, ORDER_PREFIX + groupName);
		configManager.unsetConfiguration(LAYOUT_CONFIG_GROUP, ORIENTATION_PREFIX + groupName);
		configManager.unsetConfiguration(LAYOUT_CONFIG_GROUP, SIZE_PREFIX + groupName);
	}

	private void rememberSize(TimerGroupOverlay group)
	{
		final Dimension size = group.getPreferredSize();
		if (size == null)
		{
			return;
		}

		final String key = SIZE_PREFIX + group.getName();
		final Dimension savedSize = configManager.getConfiguration(
			LAYOUT_CONFIG_GROUP,
			key,
			Dimension.class
		);
		if (!size.equals(savedSize))
		{
			configManager.setConfiguration(LAYOUT_CONFIG_GROUP, key, new Dimension(size));
		}
	}

	static boolean isMemberNamedGroup(
		String groupName,
		Collection<? extends TimerCircleOverlay> members)
	{
		for (TimerCircleOverlay member : members)
		{
			if (groupName.equals(member.getName()))
			{
				return true;
			}
		}
		return false;
	}

	private String getSavedGroup(TimerCircleOverlay timer)
	{
		final String value = configManager.getConfiguration(
			LAYOUT_CONFIG_GROUP,
			MEMBER_PREFIX + timer.getName()
		);
		return value == null || value.trim().isEmpty() ? null : value;
	}

	private void saveGroup(TimerCircleOverlay timer, String groupName)
	{
		final String key = MEMBER_PREFIX + timer.getName();
		if (timer.getName().equals(groupName))
		{
			configManager.unsetConfiguration(LAYOUT_CONFIG_GROUP, key);
		}
		else
		{
			configManager.setConfiguration(LAYOUT_CONFIG_GROUP, key, groupName);
		}
	}

	private List<String> loadOrder(String groupName)
	{
		final String value = configManager.getConfiguration(
			LAYOUT_CONFIG_GROUP,
			ORDER_PREFIX + groupName
		);
		if (value == null || value.isEmpty())
		{
			return Collections.emptyList();
		}

		final List<String> order = new ArrayList<>();
		Collections.addAll(order, value.split(ORDER_SEPARATOR));
		return order;
	}

	private void saveOrder(TimerGroupOverlay group)
	{
		final List<TimerCircleOverlay> members = group.getMembers();
		final List<String> names = new ArrayList<>(members.size());
		for (TimerCircleOverlay member : members)
		{
			names.add(member.getName());
		}

		configManager.setConfiguration(
			LAYOUT_CONFIG_GROUP,
			ORDER_PREFIX + group.getName(),
			String.join(ORDER_SEPARATOR, names)
		);
	}
}

package com.ringoftime;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentOrientation;

/**
 * Hosts one or more timer rings in a resizable wrapping overlay.
 */
final class TimerGroupOverlay extends OverlayPanel
{
	static final String DETACH_OPTION = "Detach";
	static final String FLIP_OPTION = "Flip";

	private static final int DEFAULT_WRAP_COUNT = 4;

	private final Client client;
	private final RingOfTimeConfig config;
	private final TimerGroupManager manager;
	private final String name;
	private final List<TimerCircleOverlay> members = new CopyOnWriteArrayList<>();
	private final Map<TimerCircleOverlay, Rectangle> visibleMemberBounds = new LinkedHashMap<>();

	private ComponentOrientation orientation;
	private TimerCircleOverlay hoveredTimer;
	private Point lastAutomaticLocation;
	private boolean automaticLayoutEnabled;

	TimerGroupOverlay(
		Client client,
		RingOfTimePlugin plugin,
		RingOfTimeConfig config,
		TimerGroupManager manager,
		String name,
		ComponentOrientation orientation)
	{
		super(plugin);
		this.client = client;
		this.config = config;
		this.manager = manager;
		this.name = name;
		this.orientation = orientation;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_MED);
		setMovable(true);
		setSnappable(true);
		setResettable(true);
		setResizable(true);
		setMinimumSize(32);
		setDragTargetable(true);
		setClearChildren(false);

		panelComponent.setBackgroundColor(null);
		panelComponent.setBorder(new Rectangle());
		panelComponent.setWrap(true);
	}

	@Override
	public String getName()
	{
		return name;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final boolean menuOpen = client.isMenuOpen();
		if (!menuOpen)
		{
			hoveredTimer = null;
		}

		final Dimension cellSize = TimerLabelLayout.estimateMaximumDimension(config);
		final int horizontalGap = config.ringGroupHorizontalSpacing();
		final int verticalGap = config.ringGroupVerticalSpacing();
		final int uiPadding = config.ringGroupUiPadding();
		final List<TimerCircleComponent> visibleComponents = new ArrayList<>();
		for (TimerCircleOverlay member : members)
		{
			if (member.isTimerActive())
			{
				final TimerCircleComponent component = new TimerCircleComponent(member);
				visibleComponents.add(component);
				panelComponent.getChildren().add(component);
			}
		}

		if (visibleComponents.isEmpty())
		{
			synchronized (visibleMemberBounds)
			{
				visibleMemberBounds.clear();
			}
			panelComponent.getChildren().clear();
			return null;
		}

		panelComponent.setPreferredSize(new Dimension(
			DEFAULT_WRAP_COUNT * (cellSize.width + horizontalGap) + uiPadding * 2,
			DEFAULT_WRAP_COUNT * (cellSize.height + verticalGap) + uiPadding * 2
		));
		panelComponent.setBorder(new Rectangle(uiPadding, uiPadding, uiPadding, uiPadding));
		panelComponent.setGap(new Point(horizontalGap, verticalGap));
		panelComponent.setOrientation(orientation);

		final Dimension dimension = super.render(graphics);
		try
		{
			final net.runelite.api.Point clientMouse = client.getMouseCanvasPosition();
			final Point mouse = new Point(clientMouse.getX(), clientMouse.getY());
			final Map<TimerCircleOverlay, Rectangle> renderedBounds = new LinkedHashMap<>();
			boolean foundHoveredTimer = false;
			for (TimerCircleComponent component : visibleComponents)
			{
				final Rectangle childBounds = new Rectangle(component.getBounds());
				childBounds.translate(getBounds().x, getBounds().y);
				renderedBounds.put(component.getTimer(), childBounds);
				if (!foundHoveredTimer && childBounds.contains(mouse))
				{
					foundHoveredTimer = true;
					if (!menuOpen)
					{
						hoveredTimer = component.getTimer();
					}
				}
			}

			synchronized (visibleMemberBounds)
			{
				visibleMemberBounds.clear();
				visibleMemberBounds.putAll(renderedBounds);
			}
		}
		finally
		{
			panelComponent.getChildren().clear();
		}
		return dimension;
	}

	@Override
	public List<OverlayMenuEntry> getMenuEntries()
	{
		if (hoveredTimer == null)
		{
			return Collections.emptyList();
		}

		final List<OverlayMenuEntry> entries = new ArrayList<>(2);
		if (members.size() > 1)
		{
			entries.add(new OverlayMenuEntry(
				MenuAction.RUNELITE_OVERLAY,
				DETACH_OPTION,
				hoveredTimer.getName()
			));
		}
		if (getActiveMemberCount() > 1)
		{
			entries.add(new OverlayMenuEntry(
				MenuAction.RUNELITE_OVERLAY,
				FLIP_OPTION,
				"Ring of Time group"
			));
		}
		return entries;
	}

	@Override
	public boolean onDrag(Overlay source)
	{
		if (!(source instanceof TimerGroupOverlay))
		{
			return false;
		}

		return manager.merge((TimerGroupOverlay) source, this);
	}

	void initializeAutomaticLayout()
	{
		automaticLayoutEnabled = getPreferredLocation() == null
			&& getPreferredPosition() == null
			&& getPreferredSize() == null;
		lastAutomaticLocation = null;
	}

	boolean applyAutomaticLocation(Point location)
	{
		if (!automaticLayoutEnabled)
		{
			return false;
		}

		final Point currentLocation = getPreferredLocation();
		if (getPreferredSize() != null
			|| getPreferredPosition() != null
			|| (lastAutomaticLocation == null && currentLocation != null)
			|| (lastAutomaticLocation != null && !lastAutomaticLocation.equals(currentLocation)))
		{
			automaticLayoutEnabled = false;
			return false;
		}

		final Point locationCopy = new Point(location);
		setPreferredPosition(null);
		setPreferredLocation(locationCopy);
		lastAutomaticLocation = new Point(locationCopy);
		return true;
	}

	void markManaged()
	{
		automaticLayoutEnabled = false;
	}

	void placeDetachedAt(Point location)
	{
		markManaged();
		setPreferredPosition(null);
		setPreferredLocation(new Point(location));
	}

	void addMember(TimerCircleOverlay timer)
	{
		if (!members.contains(timer))
		{
			members.add(timer);
		}
	}

	void removeMember(TimerCircleOverlay timer)
	{
		members.remove(timer);
		if (hoveredTimer == timer)
		{
			hoveredTimer = null;
		}
	}

	List<TimerCircleOverlay> getMembers()
	{
		return new ArrayList<>(members);
	}

	/**
	 * Returns the visible ring under a canvas point when this group has enough
	 * visible members to reorder.
	 */
	MemberHit findMemberAt(Point canvasPoint)
	{
		synchronized (visibleMemberBounds)
		{
			if (visibleMemberBounds.size() < 2)
			{
				return null;
			}

			for (Map.Entry<TimerCircleOverlay, Rectangle> entry : visibleMemberBounds.entrySet())
			{
				if (entry.getValue().contains(canvasPoint))
				{
					return new MemberHit(this, entry.getKey());
				}
			}
		}

		return null;
	}

	/**
	 * Inserts a member immediately before or after another group member.
	 */
	boolean moveMember(
		TimerCircleOverlay dragged,
		TimerCircleOverlay target,
		boolean insertAfter)
	{
		if (dragged == null || target == null || dragged == target)
		{
			return false;
		}

		final List<TimerCircleOverlay> originalOrder = new ArrayList<>(members);
		final int draggedIndex = members.indexOf(dragged);
		int targetIndex = members.indexOf(target);
		if (draggedIndex < 0 || targetIndex < 0)
		{
			return false;
		}

		members.remove(draggedIndex);
		targetIndex = members.indexOf(target);
		members.add(targetIndex + (insertAfter ? 1 : 0), dragged);
		return !members.equals(originalOrder);
	}

	DragLayout captureDragLayout()
	{
		synchronized (visibleMemberBounds)
		{
			return visibleMemberBounds.size() < 2
				? null
				: new DragLayout(visibleMemberBounds);
		}
	}

	/**
	 * Applies known saved names first and leaves newly introduced timers in
	 * their normal order at the end.
	 */
	void restoreMemberOrder(List<String> savedOrder)
	{
		if (savedOrder == null || savedOrder.isEmpty() || members.size() < 2)
		{
			return;
		}

		final List<TimerCircleOverlay> remaining = new ArrayList<>(members);
		final List<TimerCircleOverlay> restored = new ArrayList<>(members.size());
		for (String name : savedOrder)
		{
			for (int index = 0; index < remaining.size(); index++)
			{
				final TimerCircleOverlay member = remaining.get(index);
				if (member.getName().equals(name))
				{
					restored.add(member);
					remaining.remove(index);
					break;
				}
			}
		}

		restored.addAll(remaining);
		members.clear();
		members.addAll(restored);
	}

	TimerCircleOverlay getHoveredTimer()
	{
		return hoveredTimer;
	}

	boolean isTimerActive()
	{
		return getActiveMemberCount() > 0;
	}

	int estimateAutomaticHeight(Dimension cellSize)
	{
		final int count = getActiveMemberCount();
		if (count == 0)
		{
			return 0;
		}

		final int rows = orientation == ComponentOrientation.VERTICAL
			? Math.min(count, DEFAULT_WRAP_COUNT)
			: (count + DEFAULT_WRAP_COUNT - 1) / DEFAULT_WRAP_COUNT;
		return rows * cellSize.height
			+ Math.max(0, rows - 1) * config.ringGroupVerticalSpacing()
			+ config.ringGroupUiPadding() * 2;
	}

	ComponentOrientation flip()
	{
		orientation = orientation == ComponentOrientation.HORIZONTAL
			? ComponentOrientation.VERTICAL
			: ComponentOrientation.HORIZONTAL;
		return orientation;
	}

	ComponentOrientation getOrientation()
	{
		return orientation;
	}

	private int getActiveMemberCount()
	{
		int count = 0;
		for (TimerCircleOverlay member : members)
		{
			if (member.isTimerActive())
			{
				count++;
			}
		}
		return count;
	}

	/**
	 * Identifies both the group and ring found during mouse hit testing.
	 */
	static final class MemberHit
	{
		private final TimerGroupOverlay group;
		private final TimerCircleOverlay member;

		private MemberHit(TimerGroupOverlay group, TimerCircleOverlay member)
		{
			this.group = group;
			this.member = member;
		}

		TimerGroupOverlay getGroup()
		{
			return group;
		}

		TimerCircleOverlay getMember()
		{
			return member;
		}
	}

	static final class InsertionTarget
	{
		private final TimerCircleOverlay member;
		private final boolean insertAfter;

		private InsertionTarget(TimerCircleOverlay member, boolean insertAfter)
		{
			this.member = member;
			this.insertAfter = insertAfter;
		}

		TimerCircleOverlay getMember()
		{
			return member;
		}

		boolean isInsertAfter()
		{
			return insertAfter;
		}
	}

	static final class DragLayout
	{
		private final Map<TimerCircleOverlay, Rectangle> slots;

		private DragLayout(Map<TimerCircleOverlay, Rectangle> visibleMemberBounds)
		{
			this.slots = new LinkedHashMap<>();
			for (Map.Entry<TimerCircleOverlay, Rectangle> entry : visibleMemberBounds.entrySet())
			{
				this.slots.put(entry.getKey(), new Rectangle(entry.getValue()));
			}
		}

		InsertionTarget findInsertionAt(Point canvasPoint, TimerCircleOverlay dragged)
		{
			int nearestSlotIndex = -1;
			int slotIndex = 0;
			double nearestDistance = Double.MAX_VALUE;
			for (Map.Entry<TimerCircleOverlay, Rectangle> entry : slots.entrySet())
			{
				final Rectangle bounds = entry.getValue();
				final double xDistance = canvasPoint.x - bounds.getCenterX();
				final double yDistance = canvasPoint.y - bounds.getCenterY();
				final double distance = xDistance * xDistance + yDistance * yDistance;
				if (distance < nearestDistance)
				{
					nearestDistance = distance;
					nearestSlotIndex = slotIndex;
				}
				slotIndex++;
			}

			final List<TimerCircleOverlay> remaining = new ArrayList<>(slots.keySet());
			if (nearestSlotIndex < 0 || !remaining.remove(dragged) || remaining.isEmpty())
			{
				return null;
			}

			if (nearestSlotIndex >= remaining.size())
			{
				return new InsertionTarget(remaining.get(remaining.size() - 1), true);
			}

			return new InsertionTarget(remaining.get(nearestSlotIndex), false);
		}
	}
}

package com.ringoftime;

import java.awt.Point;
import java.awt.event.InputEvent;
import java.awt.event.MouseEvent;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.client.input.MouseListener;

/**
 * Handles Ctrl+Alt-drag insertion inside a ring group.
 */
final class TimerGroupReorderInput implements MouseListener
{
	private static final int REORDER_MODIFIERS =
		InputEvent.CTRL_DOWN_MASK | InputEvent.ALT_DOWN_MASK;

	private final Client client;
	private final TimerGroupManager manager;
	private TimerGroupOverlay activeGroup;
	private TimerCircleOverlay draggedMember;
	private TimerGroupOverlay.DragLayout dragLayout;
	private TimerCircleOverlay lastTarget;
	private boolean lastInsertAfter;
	private double eventScaleX = 1.0;
	private double eventScaleY = 1.0;

	TimerGroupReorderInput(Client client, TimerGroupManager manager)
	{
		this.client = client;
		this.manager = manager;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent event)
	{
		if (!hasReorderModifiers(event) || !SwingUtilities.isLeftMouseButton(event))
		{
			return event;
		}

		final Point canvasPoint = getCanvasMousePoint(event);
		calibrateEventScale(event.getPoint(), canvasPoint);
		final TimerGroupOverlay.MemberHit hit = manager.findMemberAt(canvasPoint);
		if (hit == null)
		{
			return event;
		}

		activeGroup = hit.getGroup();
		draggedMember = hit.getMember();
		dragLayout = activeGroup.captureDragLayout();
		event.consume();
		return event;
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent event)
	{
		if (draggedMember == null)
		{
			return event;
		}

		final Point canvasPoint = scaleEventPoint(event.getPoint());
		final TimerGroupOverlay.InsertionTarget target = dragLayout == null
			? null
			: dragLayout.findInsertionAt(canvasPoint, draggedMember);
		if (target != null && (target.getMember() != lastTarget
			|| target.isInsertAfter() != lastInsertAfter)
		)
		{
			manager.reorder(
				activeGroup,
				draggedMember,
				target.getMember(),
				target.isInsertAfter()
			);
			lastTarget = target.getMember();
			lastInsertAfter = target.isInsertAfter();
		}

		event.consume();
		return event;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent event)
	{
		if (draggedMember != null)
		{
			clearDrag();
			event.consume();
		}
		return event;
	}

	@Override
	public MouseEvent mouseExited(MouseEvent event)
	{
		clearDrag();
		return event;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent event)
	{
		return event;
	}

	@Override
	public MouseEvent mouseEntered(MouseEvent event)
	{
		return event;
	}

	@Override
	public MouseEvent mouseMoved(MouseEvent event)
	{
		return event;
	}

	static boolean hasReorderModifiers(MouseEvent event)
	{
		return (event.getModifiersEx() & REORDER_MODIFIERS) == REORDER_MODIFIERS;
	}

	private Point getCanvasMousePoint(MouseEvent event)
	{
		if (client == null)
		{
			return event.getPoint();
		}

		final net.runelite.api.Point canvasPoint = client.getMouseCanvasPosition();
		return new Point(canvasPoint.getX(), canvasPoint.getY());
	}

	private void calibrateEventScale(Point eventPoint, Point canvasPoint)
	{
		eventScaleX = calculateScale(eventPoint.x, canvasPoint.x);
		eventScaleY = calculateScale(eventPoint.y, canvasPoint.y);
	}

	private static double calculateScale(int eventCoordinate, int canvasCoordinate)
	{
		return eventCoordinate > 0 && canvasCoordinate > 0
			? (double) eventCoordinate / canvasCoordinate
			: 1.0;
	}

	private Point scaleEventPoint(Point eventPoint)
	{
		return new Point(
			(int) Math.round(eventPoint.x / eventScaleX),
			(int) Math.round(eventPoint.y / eventScaleY)
		);
	}

	private void clearDrag()
	{
		activeGroup = null;
		draggedMember = null;
		dragLayout = null;
		lastTarget = null;
		lastInsertAfter = false;
		eventScaleX = 1.0;
		eventScaleY = 1.0;
	}
}

package com.ringoftime;

import com.ringoftime.RingOfTimeConfig.PlusMinusPosition;
import com.ringoftime.RingOfTimeConfig.IconPosition;
import com.ringoftime.RingOfTimeConfig.TimerPosition;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.FontMetrics;
import java.awt.Rectangle;

/**
 * Measures the positioned timer, +/- badge, and movable icon as one overlay.
 *
 * <p>The countdown uses its selected vertical anchor. Icon and +/- bounds move
 * away from the center if necessary and stack instead of overlapping. Above
 * and under icon positions extend the component only in that direction.</p>
 */
final class TimerLabelLayout
{
	private static final int LABEL_GAP = 3;
	private static final int STACK_GAP = 2;
	private static final int HORIZONTAL_PADDING = 3;
	private static final int VERTICAL_PADDING = 1;

	private final Dimension dimension;
	private final int ringX;
	private final int ringY;
	private final Rectangle timerBounds;
	private final Rectangle plusMinusBounds;
	private final Rectangle iconBounds;

	private TimerLabelLayout(
		Dimension dimension,
		int ringX,
		int ringY,
		Rectangle timerBounds,
		Rectangle plusMinusBounds,
		Rectangle iconBounds)
	{
		this.dimension = dimension;
		this.ringX = ringX;
		this.ringY = ringY;
		this.timerBounds = timerBounds;
		this.plusMinusBounds = plusMinusBounds;
		this.iconBounds = iconBounds;
	}

	/**
	 * Measures the current strings and returns positions relative to the ring.
	 */
	static TimerLabelLayout create(
		int ringSize,
		FontMetrics timerMetrics,
		String timerText,
		TimerPosition timerPosition,
		FontMetrics plusMinusMetrics,
		String plusMinusText,
		PlusMinusPosition plusMinusPosition,
		IconPosition iconPosition)
	{
		final int timerWidth = timerText == null
			? 0
			: timerMetrics.stringWidth(timerText) + HORIZONTAL_PADDING * 2;
		final int plusMinusWidth = plusMinusText == null
			? 0
			: plusMinusMetrics.stringWidth(plusMinusText) + HORIZONTAL_PADDING * 2;
		final int timerHeight = timerMetrics.getHeight() + VERTICAL_PADDING * 2;
		final int plusMinusHeight = plusMinusMetrics.getHeight() + VERTICAL_PADDING * 2;

		return createWithSizes(
			ringSize,
			timerWidth,
			timerText == null || !timerPosition.isShown() ? 0 : timerHeight,
			timerPosition,
			plusMinusWidth,
			plusMinusText == null ? 0 : plusMinusHeight,
			plusMinusPosition,
			iconPosition
		);
	}

	/**
	 * Returns a conservative component size for automatic vertical placement
	 * before a particular countdown string has been rendered.
	 */
	static Dimension estimateMaximumDimension(RingOfTimeConfig config)
	{
		final int timerFontSize = config.timerFontSize();
		final int plusMinusFontSize = config.plusMinusFontSize();
		final int timerWidth = timerFontSize * 5 + HORIZONTAL_PADDING * 2;
		final int plusMinusWidth = plusMinusFontSize * 3 + HORIZONTAL_PADDING * 2;
		final int timerHeight = config.timerPosition().isShown() ? timerFontSize + 8 : 0;
		final int plusMinusHeight = plusMinusFontSize + 8;

		final TimerLabelLayout buffLayout = createWithSizes(
			config.ringSize(),
			timerWidth,
			timerHeight,
			config.timerPosition(),
			plusMinusWidth,
			config.buffPlusMinusPosition() == PlusMinusPosition.OFF ? 0 : plusMinusHeight,
			config.buffPlusMinusPosition(),
			config.iconPosition()
		);
		final TimerLabelLayout debuffLayout = createWithSizes(
			config.ringSize(),
			timerWidth,
			timerHeight,
			config.timerPosition(),
			plusMinusWidth,
			config.debuffPlusMinusPosition() == PlusMinusPosition.OFF ? 0 : plusMinusHeight,
			config.debuffPlusMinusPosition(),
			config.iconPosition()
		);

		final TimerLabelLayout effectLayout = createWithSizes(
			config.ringSize(),
			timerWidth,
			timerHeight,
			config.timerPosition(),
			0,
			0,
			PlusMinusPosition.OFF,
			config.effectIconPosition()
		);

		return new Dimension(
			Math.max(
				Math.max(buffLayout.dimension.width, debuffLayout.dimension.width),
				effectLayout.dimension.width
			),
			Math.max(
				Math.max(buffLayout.dimension.height, debuffLayout.dimension.height),
				effectLayout.dimension.height
			)
		);
	}

	/**
	 * Returns the clear center diameter inside the active outer or inner ring.
	 */
	static int getClearCenterSize(
		int ringSize,
		int outerThickness,
		int outlineThickness,
		boolean innerRingVisible)
	{
		final double edgeMargin = Math.max(1d, outlineThickness);
		if (!innerRingVisible)
		{
			final double outerDiameter = ringSize - outerThickness - edgeMargin * 2d;
			return Math.max(
				8,
				(int) Math.floor(outerDiameter - outerThickness - outlineThickness * 2d)
			);
		}

		final int innerThickness = Math.max(2, Math.min(4, (outerThickness + 1) / 2));
		final double gap = Math.max(2d, outerThickness * 0.35d);
		final double inset = outerThickness
			+ edgeMargin
			+ outlineThickness
			+ gap
			+ innerThickness / 2d;
		final double innerDiameter = ringSize - inset * 2d;
		return Math.max(
			8,
			(int) Math.floor(innerDiameter - innerThickness - outlineThickness * 2d)
		);
	}

	/**
	 * Treats the configured font size as a maximum and shrinks countdown text
	 * until both its width and height fit inside the clear center diameter.
	 */
	static Font fitTimerFont(
		Graphics2D graphics,
		Font preferredFont,
		String text,
		int clearCenterSize)
	{
		if (text == null)
		{
			return preferredFont;
		}

		final int available = Math.max(6, clearCenterSize - 2);
		for (int size = Math.round(preferredFont.getSize2D()); size >= 5; size--)
		{
			final Font candidate = preferredFont.deriveFont((float) size);
			final FontMetrics metrics = graphics.getFontMetrics(candidate);
			if (metrics.stringWidth(text) + 1 <= available
				&& metrics.getHeight() + 1 <= available)
			{
				return candidate;
			}
		}

		return preferredFont.deriveFont(5f);
	}
	private static TimerLabelLayout createWithSizes(
		int ringSize,
		int timerWidth,
		int timerHeight,
		TimerPosition timerPosition,
		int plusMinusWidth,
		int plusMinusHeight,
		PlusMinusPosition plusMinusPosition,
		IconPosition iconPosition)
	{
		final Rectangle ringBounds = new Rectangle(0, 0, ringSize, ringSize);
		final Rectangle timerBounds = timerHeight == 0
			? null
			: placeTimer(ringSize, timerWidth, timerHeight, timerPosition);
		Rectangle iconBounds = placeIcon(ringSize, iconPosition);
		Rectangle plusMinusBounds = plusMinusHeight == 0
			? null
			: placePlusMinus(ringSize, plusMinusWidth, plusMinusHeight, plusMinusPosition);

		plusMinusBounds = moveAwayFromTimer(plusMinusBounds, timerBounds, isTop(plusMinusPosition));
		iconBounds = moveAwayFromTimer(iconBounds, timerBounds, isTop(iconPosition));
		if (plusMinusBounds != null && plusMinusBounds.intersects(iconBounds))
		{
			iconBounds = stackIconOutside(iconBounds, plusMinusBounds, isTop(iconPosition));
		}

		Rectangle componentBounds = new Rectangle(ringBounds);
		componentBounds = union(componentBounds, timerBounds);
		componentBounds = union(componentBounds, plusMinusBounds);
		componentBounds = union(componentBounds, iconBounds);

		return new TimerLabelLayout(
			new Dimension(componentBounds.width, componentBounds.height),
			-componentBounds.x,
			-componentBounds.y,
			timerBounds,
			plusMinusBounds,
			iconBounds
		);
	}

	private static Rectangle placeTimer(
		int ringSize,
		int width,
		int height,
		TimerPosition position)
	{
		final int x = Math.floorDiv(ringSize - width, 2);
		switch (position)
		{
			case TOP:
				return new Rectangle(x, 0, width, height);
			case MIDDLE:
				return new Rectangle(x, (ringSize - height) / 2, width, height);
			case BOTTOM:
				return new Rectangle(x, ringSize - height, width, height);
			default:
				throw new IllegalArgumentException("Unsupported timer position: " + position);
		}
	}

	private static Rectangle placeIcon(int ringSize, IconPosition position)
	{
		final int size = Math.max(14, (int) (ringSize * 0.40));
		switch (position)
		{
			case TOP_LEFT:
				return new Rectangle(0, 0, size, size);
			case TOP_RIGHT:
				return new Rectangle(ringSize - size, 0, size, size);
			case BOTTOM_RIGHT:
				return new Rectangle(ringSize - size, ringSize - size, size, size);
			case BOTTOM_LEFT:
				return new Rectangle(0, ringSize - size, size, size);
			case CENTER:
				return new Rectangle((ringSize - size) / 2, (ringSize - size) / 2, size, size);
			case ABOVE_RING:
				return new Rectangle((ringSize - size) / 2, -size - LABEL_GAP, size, size);
			case UNDER_RING:
				return new Rectangle((ringSize - size) / 2, ringSize + LABEL_GAP, size, size);
			default:
				throw new IllegalArgumentException("Unsupported icon position: " + position);
		}
	}

	private static Rectangle placePlusMinus(
		int ringSize,
		int width,
		int height,
		PlusMinusPosition position)
	{
		if (position == PlusMinusPosition.CENTER)
		{
			return new Rectangle(
				Math.floorDiv(ringSize - width, 2),
				(ringSize - height) / 2,
				width,
				height
			);
		}

		final int x = isLeft(position) ? 0 : ringSize - width;
		final int y = isTop(position) ? 0 : ringSize - height;
		return new Rectangle(x, y, width, height);
	}

	/**
	 * Keeps the center countdown readable while retaining the selected edge.
	 */
	private static Rectangle moveAwayFromTimer(
		Rectangle bounds,
		Rectangle timerBounds,
		boolean towardTop)
	{
		if (bounds == null || timerBounds == null || !bounds.intersects(timerBounds))
		{
			return bounds;
		}

		final Rectangle moved = new Rectangle(bounds);
		moved.y = towardTop
			? timerBounds.y - STACK_GAP - moved.height
			: timerBounds.y + timerBounds.height + STACK_GAP;
		return moved;
	}

	/**
	 * Preserves the configured +/- anchor and moves a colliding icon outward.
	 */
	private static Rectangle stackIconOutside(
		Rectangle iconBounds,
		Rectangle plusMinusBounds,
		boolean towardTop)
	{
		final Rectangle moved = new Rectangle(iconBounds);
		moved.y = towardTop
			? plusMinusBounds.y - STACK_GAP - moved.height
			: plusMinusBounds.y + plusMinusBounds.height + STACK_GAP;
		return moved;
	}

	private static Rectangle union(Rectangle component, Rectangle addition)
	{
		if (addition == null)
		{
			return component;
		}

		return component.union(addition);
	}

	private static boolean isTop(IconPosition position)
	{
		return position == IconPosition.TOP_LEFT
			|| position == IconPosition.TOP_RIGHT
			|| position == IconPosition.ABOVE_RING;
	}

	private static boolean isLeft(PlusMinusPosition position)
	{
		return position == PlusMinusPosition.TOP_LEFT || position == PlusMinusPosition.BOTTOM_LEFT;
	}

	private static boolean isTop(PlusMinusPosition position)
	{
		return position == PlusMinusPosition.TOP_LEFT || position == PlusMinusPosition.TOP_RIGHT;
	}

	Dimension getDimension()
	{
		return new Dimension(dimension);
	}

	int getRingX()
	{
		return ringX;
	}

	int getRingY()
	{
		return ringY;
	}

	Rectangle getTimerBounds()
	{
		return timerBounds == null ? null : new Rectangle(timerBounds);
	}

	Rectangle getPlusMinusBounds()
	{
		return plusMinusBounds == null ? null : new Rectangle(plusMinusBounds);
	}

	Rectangle getIconBounds()
	{
		return new Rectangle(iconBounds);
	}
}

package com.ringoftime;

import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class CustomUiAnchorsCompatibilityTest
{
	@Test
	public void transfersMemberAssignmentToGroupName()
	{
		final Map<String, Integer> assignments = new LinkedHashMap<>();
		assignments.put("Ring of Time - Antifire", 1);

		assertTrue(CustomUiAnchorsCompatibility.reconcileNames(
			assignments,
			"Ring of Time - Hunter",
			Arrays.asList("Ring of Time - Hunter", "Ring of Time - Antifire")
		));
		assertEquals(Integer.valueOf(1), assignments.get("Ring of Time - Hunter"));
		assertFalse(assignments.containsKey("Ring of Time - Antifire"));
	}

	@Test
	public void existingGroupAssignmentWinsOverMemberAliases()
	{
		final Map<String, Integer> assignments = new LinkedHashMap<>();
		assignments.put("Ring of Time - Hunter", 2);
		assignments.put("Ring of Time - Antifire", 1);

		assertTrue(CustomUiAnchorsCompatibility.reconcileNames(
			assignments,
			"Ring of Time - Hunter",
			Arrays.asList("Ring of Time - Hunter", "Ring of Time - Antifire")
		));
		assertEquals(Integer.valueOf(2), assignments.get("Ring of Time - Hunter"));
		assertFalse(assignments.containsKey("Ring of Time - Antifire"));
	}

	@Test
	public void leavesUnrelatedAssignmentsUntouched()
	{
		final Map<String, Integer> assignments = new LinkedHashMap<>();
		assignments.put("InfoBoxOverlay", 3);

		assertFalse(CustomUiAnchorsCompatibility.reconcileNames(
			assignments,
			"Ring of Time - Hunter",
			Arrays.asList("Ring of Time - Hunter", "Ring of Time - Antifire")
		));
		assertEquals(Integer.valueOf(3), assignments.get("InfoBoxOverlay"));
	}
}

package com.ringoftime;

import net.runelite.api.Skill;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class DivineTimerTrackerTest
{
	private static final double TOLERANCE = 0.0001d;

	private DivineTimerTracker tracker;

	@Before
	public void setUp()
	{
		tracker = new DivineTimerTracker();
	}

	@Test
	public void tracksExactPerSkillDuration()
	{
		tracker.observe(500, 400, 300, 200, 100, 0, 0, 0, 0, 1_000L);

		assertTrue(tracker.isActive(Skill.ATTACK));
		assertEquals(1d, tracker.getProgress(Skill.ATTACK, 1_000L), TOLERANCE);
		assertEquals(300, tracker.getRemainingSeconds(Skill.ATTACK, 1_000L));
		assertEquals(0.6d, tracker.getProgress(Skill.DEFENCE, 1_000L), TOLERANCE);
		assertEquals(60, tracker.getRemainingSeconds(Skill.MAGIC, 1_000L));
	}

	@Test
	public void moonlightOnlyDefenceTimerIsIgnored()
	{
		tracker.observe(0, 0, 301, 0, 0, 0, 0, 0, 300, 1_000L);

		assertFalse(tracker.isActive(Skill.DEFENCE));
	}

	@Test
	public void individualDefenceRemainsActiveOnItsFinalTick()
	{
		tracker.observe(0, 0, 1, 0, 0, 0, 0, 0, 0, 1_000L);

		assertTrue(tracker.isActive(Skill.DEFENCE));
		assertEquals(1, tracker.getRemainingSeconds(Skill.DEFENCE, 1_000L));
	}

	@Test
	public void combinationPotionKeepsDefenceDivine()
	{
		tracker.observe(0, 0, 300, 300, 0, 0, 300, 0, 300, 1_000L);

		assertTrue(tracker.isActive(Skill.DEFENCE));
		assertEquals(180, tracker.getRemainingSeconds(Skill.DEFENCE, 1_000L));
	}

	@Test
	public void changedVarbitReanchorsWithoutJumpingBackward()
	{
		tracker.observe(500, 0, 0, 0, 0, 0, 0, 0, 0, 1_000L);
		final double immediatelyBeforeChange = tracker.getProgress(Skill.ATTACK, 1_599L);

		tracker.observe(499, 0, 0, 0, 0, 0, 0, 0, 0, 1_600L);
		final double immediatelyAfterChange = tracker.getProgress(Skill.ATTACK, 1_600L);

		assertTrue(immediatelyAfterChange <= immediatelyBeforeChange);
		assertEquals(immediatelyBeforeChange, immediatelyAfterChange, 0.00001d);
	}

	@Test
	public void unchangedSamplesDoNotRestartInterpolation()
	{
		tracker.observe(500, 0, 0, 0, 0, 0, 0, 0, 0, 1_000L);
		tracker.observe(500, 0, 0, 0, 0, 0, 0, 0, 0, 1_300L);

		assertEquals(499.5d / 500d, tracker.getProgress(Skill.ATTACK, 1_300L), TOLERANCE);
	}

	@Test
	public void resetClearsEverySkill()
	{
		tracker.observe(500, 500, 500, 500, 500, 500, 0, 0, 0, 1_000L);
		tracker.reset();

		for (Skill skill : new Skill[]{
			Skill.ATTACK,
			Skill.STRENGTH,
			Skill.DEFENCE,
			Skill.RANGED,
			Skill.MAGIC})
		{
			assertFalse(tracker.isActive(skill));
		}
	}
}

package com.ringoftime;

import com.ringoftime.EffectTimerTracker.Effect;
import net.runelite.api.ChatMessageType;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Verifies effect-specific timing without starting or automating the client.
 */
public class EffectTimerTrackerTest
{
	private static final double TOLERANCE = 0.0001d;

	private EffectTimerTracker tracker;

	@Before
	public void setUp()
	{
		tracker = new EffectTimerTracker();
		tracker.reset();
	}

	@Test
	public void poisonProjectsNaturalCureAndNextDamage()
	{
		tracker.observePoison(10, 100, true);

		assertTrue(tracker.isActive(Effect.TOXIN));
		assertFalse(tracker.isVenom());
		assertFalse(tracker.isEstimated(Effect.TOXIN));
		assertEquals(1d, tracker.getOverallProgress(Effect.TOXIN, 100, 0d), TOLERANCE);
		assertEquals(182, tracker.getRemainingSeconds(Effect.TOXIN, 100, 0d));
		assertEquals(2, tracker.getNextToxinDamage());
		assertTrue(tracker.hasMultiplePoisonCycles());

		// A natural one-step poison decay preserves the original total scale.
		tracker.observePoison(9, 131, true);
		assertEquals(0.9d, tracker.getOverallProgress(Effect.TOXIN, 131, 0d), TOLERANCE);
		assertEquals(164, tracker.getRemainingSeconds(Effect.TOXIN, 131, 0d));
	}

	@Test
	public void venomUsesARepeatingHitCycleThenCanBecomePoison()
	{
		tracker.observePoison(EffectTimerTracker.VENOM_THRESHOLD, 20, true);

		assertTrue(tracker.isVenom());
		assertEquals(6, tracker.getNextToxinDamage());
		assertEquals(1d, tracker.getOverallProgress(Effect.TOXIN, 20, 0d), TOLERANCE);
		assertEquals(19, tracker.getRemainingSeconds(Effect.TOXIN, 20, 0d));
		assertFalse(tracker.hasMultiplePoisonCycles());

		// An actual game-state transition reveals a new full green poison timer.
		tracker.observePoison(25, 30, true);
		assertFalse(tracker.isVenom());
		assertEquals(5, tracker.getNextToxinDamage());
		assertEquals(1d, tracker.getOverallProgress(Effect.TOXIN, 30, 0d), TOLERANCE);
		assertEquals(455, tracker.getRemainingSeconds(Effect.TOXIN, 30, 0d));
	}

	@Test
	public void antipoisonAndAntivenomProtectionUseNegativePoisonValues()
	{
		tracker.observeAntipoison(-10, 100, true);

		assertTrue(tracker.isActive(Effect.ANTIPOISON));
		assertFalse(tracker.isAntivenomProtection());
		assertFalse(tracker.isEstimated(Effect.ANTIPOISON));
		assertEquals(1d, tracker.getOverallProgress(Effect.ANTIPOISON, 100, 0d), TOLERANCE);
		assertEquals(180, tracker.getRemainingSeconds(Effect.ANTIPOISON, 100, 0d));

		// A normal 30-tick block decrease preserves the original denominator.
		tracker.observeAntipoison(-9, 130, true);
		assertEquals(0.9d, tracker.getOverallProgress(Effect.ANTIPOISON, 130, 0d), TOLERANCE);
		assertEquals(162, tracker.getRemainingSeconds(Effect.ANTIPOISON, 130, 0d));

		// Values below RuneLite's cutoff identify anti-venom protection.
		tracker.observeAntipoison(-40, 200, true);
		assertTrue(tracker.isAntivenomProtection());
		assertEquals(36, tracker.getRemainingSeconds(Effect.ANTIPOISON, 200, 0d));
		assertEquals(1d, tracker.getOverallProgress(Effect.ANTIPOISON, 200, 0d), TOLERANCE);

		tracker.observeAntipoison(0, 201, true);
		assertFalse(tracker.isActive(Effect.ANTIPOISON));
		assertFalse(tracker.isAntivenomProtection());
	}

	@Test
	public void staminaVarbitIsSmoothedAndRefreshes()
	{
		tracker.observeStamina(12, true, 0, true);
		assertEquals(72, tracker.getRemainingSeconds(Effect.STAMINA, 0, 0d));
		assertEquals(5d / 6d, tracker.getOverallProgress(Effect.STAMINA, 20, 0d), TOLERANCE);

		// Increasing the duration starts a new full countdown denominator.
		tracker.observeStamina(15, true, 20, true);
		assertEquals(1d, tracker.getOverallProgress(Effect.STAMINA, 20, 0d), TOLERANCE);
		assertEquals(90, tracker.getRemainingSeconds(Effect.STAMINA, 20, 0d));

		tracker.observeStamina(15, false, 21, true);
		assertFalse(tracker.isActive(Effect.STAMINA));
	}

	@Test
	public void antifireStrengthsUseTheirOwnGameUnitSizes()
	{
		tracker.observeAntifire(4, 3, 0, true);

		assertTrue(tracker.isActive(Effect.ANTIFIRE));
		assertTrue(tracker.isActive(Effect.SUPER_ANTIFIRE));
		assertEquals(72, tracker.getRemainingSeconds(Effect.ANTIFIRE, 0, 0d));
		assertEquals(36, tracker.getRemainingSeconds(Effect.SUPER_ANTIFIRE, 0, 0d));

		assertEquals(66, tracker.getRemainingSeconds(Effect.ANTIFIRE, 10, 0d));
		assertEquals(30, tracker.getRemainingSeconds(Effect.SUPER_ANTIFIRE, 10, 0d));
	}

	@Test
	public void prayerRegenerationUsesTwelveTickUnitsAndShowsNextRestore()
	{
		tracker.observePrayerRegeneration(40, 100, true);

		assertTrue(tracker.isActive(Effect.PRAYER_REGENERATION));
		assertEquals(288, tracker.getRemainingSeconds(Effect.PRAYER_REGENERATION, 100, 0d));
		assertEquals(1d, tracker.getPrayerRegenerationCycleProgress(100, 0d), TOLERANCE);
		assertEquals(0.5d, tracker.getPrayerRegenerationCycleProgress(106, 0d), TOLERANCE);

		tracker.observePrayerRegeneration(39, 112, true);
		assertEquals(39d / 40d, tracker.getOverallProgress(
			Effect.PRAYER_REGENERATION,
			112,
			0d
		), TOLERANCE);
		assertEquals(1d, tracker.getPrayerRegenerationCycleProgress(112, 0d), TOLERANCE);

		tracker.observePrayerRegeneration(50, 120, true);
		assertEquals(1d, tracker.getOverallProgress(Effect.PRAYER_REGENERATION, 120, 0d), TOLERANCE);
		assertEquals(360, tracker.getRemainingSeconds(Effect.PRAYER_REGENERATION, 120, 0d));

		tracker.observePrayerRegeneration(0, 121, true);
		assertFalse(tracker.isActive(Effect.PRAYER_REGENERATION));
	}
	@Test
	public void thrallDurationUsesBoostedMagicAndMasterTier()
	{
		tracker.observeThrallCooldown(true, 96);
		tracker.startThrall(90, false, 100);
		assertTrue(tracker.isActive(Effect.THRALL));
		assertFalse(tracker.isEstimated(Effect.THRALL));
		assertEquals(1d, tracker.getOverallProgress(Effect.THRALL, 100, 0d), TOLERANCE);
		assertEquals(54, tracker.getRemainingSeconds(Effect.THRALL, 100, 0d));
		assertEquals(0.5d, tracker.getOverallProgress(Effect.THRALL, 145, 0d), TOLERANCE);
		assertTrue(tracker.isThrallCooldownActive());
		assertEquals(13d / 17d, tracker.getThrallCooldownProgress(100, 0d), TOLERANCE);

		// Repeated active observations must not move the original cooldown anchor.
		tracker.observeThrallCooldown(true, 100);
		assertEquals(13d / 17d, tracker.getThrallCooldownProgress(100, 0d), TOLERANCE);
		assertEquals(0.5d, tracker.getThrallCooldownProgress(104, 0.5d), TOLERANCE);
		tracker.observeThrallCooldown(false, 113);
		assertFalse(tracker.isThrallCooldownActive());

		tracker.startThrall(90, true, 200);
		assertEquals(108, tracker.getRemainingSeconds(Effect.THRALL, 200, 0d));

		tracker.observeThrallActive(false);
		assertFalse(tracker.isActive(Effect.THRALL));
	}

	@Test
	public void onlySuccessfulThrallGameMessagesStartTheTimer()
	{
		final String message = "<col=ef1020>You resurrect a greater ghost thrall.</col>";
		assertTrue(RingOfTimePlugin.isThrallSummonMessage(ChatMessageType.GAMEMESSAGE, message));
		assertTrue(RingOfTimePlugin.isThrallSummonMessage(ChatMessageType.SPAM, message));
		assertFalse(RingOfTimePlugin.isThrallSummonMessage(ChatMessageType.PUBLICCHAT, message));
		assertFalse(RingOfTimePlugin.isThrallSummonMessage(
			ChatMessageType.GAMEMESSAGE,
			"<col=ef1020>You do not have enough runes.</col>"
		));
	}
}

